    local result = {}
    for index = 0, POINTER_BANK_COUNT - 1 do
        if scope[index] ~= nil then result[index] = true end
    end
    return result
end

local function bankScopeText(scope, banks)
    local parts = {}
    for index = 0, POINTER_BANK_COUNT - 1 do
        local entry = scope[index]
        if entry ~= nil then
            parts[#parts + 1] = string.format("%d=%s[%s]", index,
                pointerText(banks[index]), table.concat(entry.roles, ","))
        end
    end
    return #parts > 0 and table.concat(parts, " ") or "<none>"
end

local function resolveCompressed(encoded, banks, requireReadable)
    local value = u32(encoded)
    if value == 0 then return 0 end
    if value < 0x80000000 then return 0 end
    if not isCompressedPointerValue(value) then return 0 end
    local payload = value - 0x80000000
    local index = math.floor(payload / POINTER_BANK_SIZE)
    local base = banks and banks[index] or 0
    if not plausiblePointer(base) or base % POINTER_BANK_SIZE~=0 then return 0 end
    local pointer = base + (payload % POINTER_BANK_SIZE)
    if requireReadable and not readableAddress(pointer, 4) then return 0 end
    return plausiblePointer(pointer) and pointer or 0
end

local function resolveRequiredCompressed(encoded, banks, requireReadable)
    if not isCompressedPointerValue(encoded) then
        return nil, "outside compressed-pointer range"
    end
    local pointer = resolveCompressed(encoded, banks, requireReadable)
    if pointer == 0 then return nil, "bank or target unavailable" end
    return pointer, nil
end

local function resolveExactRoute()
    local item = safeReadByte(EQUIPPED_WEAPON_RVA, false)
    if item ~= CONFIG.KINGDOM_KEY_ITEM_ID then
        return nil, string.format("Kingdom Key not equipped (item=0x%02X)", item or 0)
    end
    local sora = safeReadLong(SORA_POINTER_RVA, false) or 0
    if not readableAddress(sora, 0x180) then return nil, "field Sora unavailable" end
    local banks = readBankBases()
    if banks==nil then return nil,"complete pointer bank table unavailable" end
    local tableReference = safeReadInt(
        sora + WEAPON_RESOURCE_TABLE_REFERENCE_OFFSET, true) or 0
    local tableAddress = resolveCompressed(tableReference, banks, true)
    if tableAddress == 0 then return nil, "Sora weapon table unavailable" end
    local menvReference = safeReadInt(tableAddress, true) or 0
    local menvAddress = resolveCompressed(menvReference, banks, true)
    if menvAddress == 0 or safeReadInt(menvAddress, true) ~= EXPECTED_MENV_TAG then
        return nil, "weapon table[0] exact MENV unavailable"
    end
    local wpnBase = menvAddress - EXPECTED_MENV_OFFSET
    if not readableAddress(wpnBase, 0x10)
        or not readableAddress(wpnBase + EXPECTED_WPN_SIZE - 0x10, 0x10) then
        return nil, "calculated WPN image is not fully readable"
    end
    if safeReadInt(wpnBase, true) ~= EXPECTED_WPN_HEADER
        or safeReadInt(wpnBase + 0x04, true) ~= EXPECTED_MAIN_OFFSET
        or safeReadInt(wpnBase + 0x08, true) ~= EXPECTED_MENV_OFFSET
        or safeReadInt(wpnBase + 0x0C, true) ~= EXPECTED_WPN_SIZE then
        return nil, "exact Kingdom Key WPN header mismatch"
    end
    return {
        sora = sora,
        tableReference = tableReference,
        tableAddress = tableAddress,
        menvReference = menvReference,
        menvAddress = menvAddress,
        wpnBase = wpnBase,
        banks = banks,
    }, nil
end

local function coreRouteKey(route)
    return string.format("%X/%08X/%X/%08X/%X/%X",
        route.sora, route.tableReference, route.tableAddress,
        route.menvReference, route.menvAddress, route.wpnBase)
end

local function routeText(route)
    return string.format(
        "sora=%s table_ref=%s table=%s menv_ref=%s menv=%s wpn=%s",
        pointerText(route.sora), valueText(route.tableReference),
        pointerText(route.tableAddress), valueText(route.menvReference),
        pointerText(route.menvAddress), pointerText(route.wpnBase))
end

local function decodeRecordLayout(recordBytes, recordAddress, route)
    if recordBytes == nil or #recordBytes ~= CONFIG.RECORD_BYTES then
        return nil, "exact 0x3C record unavailable"
    end
    local encodedBase = decodeU32(recordBytes, 1)
    local blockBase, baseReason = resolveRequiredCompressed(
        encodedBase, route.banks, true)
    if blockBase == nil then
        return nil, "record+0x00 malformed: " .. tostring(baseReason)
    end
    local layout = {
        blockBase = blockBase,
        encodedBase = encodedBase,
        identity = decodeU32(recordBytes, 0x30 + 1),
        state14 = decodeU32(recordBytes, 0x14 + 1),
        links = {},
        canonicalLinks = true,
        deviations = {},
    }
    for _, sourceOffset in ipairs(CANONICAL_RECORD_LINK_ORDER) do
        local encoded = decodeU32(recordBytes, sourceOffset + 1)
        local target, reason = resolveRequiredCompressed(
            encoded, route.banks, false)
        if target == nil then
            return nil, string.format("record+0x%02X malformed: %s",
                sourceOffset, tostring(reason))
        end
        local expected = blockBase + CANONICAL_RECORD_LINKS[sourceOffset]
        layout.links[sourceOffset] = {
            encoded = encoded, target = target, expected = expected,
        }
        if target ~= expected then
            layout.canonicalLinks = false
            layout.deviations[#layout.deviations + 1] = string.format(
                "+%02X=%s(expected %s)", sourceOffset,
                pointerText(target), pointerText(expected))
        end
    end
    local ownerEncoded = decodeU32(recordBytes, 0x38 + 1)
    local ownerTarget, ownerReason = resolveRequiredCompressed(
        ownerEncoded, route.banks, false)
    if ownerTarget == nil then
        return nil, "record+0x38 malformed: " .. tostring(ownerReason)
    end
    layout.ownerEncoded = ownerEncoded
    layout.ownerTarget = ownerTarget
    layout.ownerExpected = route.wpnBase + 0x80
    layout.ownerCanonical = ownerTarget == layout.ownerExpected
    layout.cell24 = layout.links[0x24].target + 0x70
    layout.cell28 = layout.links[0x28].target + 0x50
    layout.aliasAddress = blockBase + TARGET_BACKREFERENCE_OFFSET
    layout.viewsAlias = layout.cell24 == layout.cell28
    layout.aliasCanonical = layout.viewsAlias
        and layout.cell24 == layout.aliasAddress
    if layout.identity == nil then return nil, "record identity unreadable" end
    layout.poolOrigin = recordAddress
        - layout.identity * CONFIG.RECORD_STRIDE
    return layout, nil
end

local function blockProvenance(layout, route)
    if layout == nil or route == nil then return nil, "layout/route absent" end
    local bankIndex = compressedBankIndex(layout.encodedBase)
    if bankIndex == nil then return nil, "B encoding has no compressed bank" end
    local bankBase = route.banks[bankIndex]
    if not plausiblePointer(bankBase) then
        return nil, "B compressed bank base unavailable"
    end
    return {
        encoded = layout.encodedBase,
        bankIndex = bankIndex,
        bankBase = bankBase,
        address = layout.blockBase,
        rebaseCount = 0,
    }, nil
end

local function resolveTrackedBlock(provenance, route, relevant, role)
    if provenance == nil then return nil, nil, nil end
    local currentBankBase = route.banks[provenance.bankIndex]
    if not plausiblePointer(currentBankBase) then
        return nil, string.format(
            "%s compressed bank %d is unavailable",
            role, provenance.bankIndex), nil
    end
    addRelevantBank(relevant, provenance.encoded, role)
    local resolved, reason = resolveRequiredCompressed(
        provenance.encoded, route.banks, true)
    if resolved == nil then
        return nil, role .. " could not be re-resolved: "
            .. tostring(reason), nil
    end
    local staged = nil
    if currentBankBase ~= provenance.bankBase
        or resolved ~= provenance.address then
        staged = {
            provenance = provenance,
            role = role,
            bankBase = currentBankBase,
            address = resolved,
        }
    end
    return resolved, nil, staged
end

local function captureRegistrationFocus()
    local before, reason = resolveExactRoute()
    if before == nil then return nil, reason end
    local animation = safeReadByte(before.sora + ANIMATION_OFFSET, true)
    if animation == nil then return nil, "animation unreadable" end

    local relevant = {}
    addRelevantBank(relevant, before.tableReference, "Sora+14C")
    addRelevantBank(relevant, before.menvReference, "table+00")

    local descriptor = safeReadArray(before.wpnBase + TRAIL_DESCRIPTOR_OFFSET,
        TRAIL_DESCRIPTOR_BYTES, true)
    local tableFocus = safeReadArray(before.tableAddress + TABLE_FOCUS_OFFSET,
        TABLE_FOCUS_BYTES, true)
    if descriptor == nil then return nil, "trail descriptor unreadable" end
    if tableFocus == nil then return nil, "table focus unreadable" end
    local runtimeKey = decodeU32(descriptor, TRAIL_RUNTIME_KEY_INDEX) or 0
    local runtimeTarget = 0
    local runtimeMode = "ZERO"
    if runtimeKey ~= 0 and (not isCompressedPointerValue(runtimeKey) or runtimeKey >= 0xA0000000) then
        runtimeMode="UNRESOLVED_RAW_KEY"
    elseif runtimeKey ~= 0 then
        runtimeMode="VERIFIED_BANKED_RANGE"
        addRelevantBank(relevant, runtimeKey, "WPN+42F8")
        local target, targetReason = resolveRequiredCompressed(
            runtimeKey, before.banks, false)
        if target == nil then
            return nil, "descriptor runtime key malformed: "
                .. tostring(targetReason)
        end
        runtimeTarget = target
    end

    local table28Index = 0x28 - TABLE_FOCUS_OFFSET + 1
    local recordPointer = decodeU64(tableFocus, table28Index)
    local low = decodeU32(tableFocus, table28Index) or 0
    local high = decodeU32(tableFocus, table28Index + 4) or 0
    if recordPointer == nil and (low ~= 0 or high ~= 0) then
        return nil, "table+0x28 contained a malformed qword"
    end
    recordPointer = recordPointer or 0

    local recordBytes, layout
    if recordPointer ~= 0 then
        recordBytes = safeReadArray(recordPointer, CONFIG.RECORD_BYTES, true)
        if recordBytes == nil then return nil, "table+0x28 record unreadable" end
        for _, offset in ipairs(CANONICAL_RECORD_LINK_ORDER) do
            addRelevantBank(relevant, decodeU32(recordBytes, offset + 1),
                string.format("record+%02X", offset))
        end
        addRelevantBank(relevant, decodeU32(recordBytes, 0x38 + 1),
            "record+38")
        local layoutReason
        layout, layoutReason = decodeRecordLayout(recordBytes,
            recordPointer, before)
        if layout == nil then return nil, layoutReason end
    end

    -- The native B provenance remains independently live for the rest of the
    -- run.  Re-resolve it through its captured compressed bank every frame;
    -- an absolute address is never trusted after retirement.
    local nativeBlockBase, nativeBlockReason, nativeBlockUpdate =
        resolveTrackedBlock(
        R.nativeBlockProvenance, before, relevant, "native_B")
    if nativeBlockReason ~= nil then return nil, nativeBlockReason end
    local observationBlockBase, observationBlockReason, observationBlockUpdate =
        resolveTrackedBlock(
        R.observationBlockProvenance, before, relevant, "observation_B")
    if observationBlockReason ~= nil then return nil, observationBlockReason end
    local blockBase = layout and layout.blockBase
        or observationBlockBase or nativeBlockBase
    local backrefBytes, backref
    if blockBase ~= nil then
        backrefBytes = safeReadArray(
            blockBase + TARGET_BACKREFERENCE_OFFSET, 8, true)
        if backrefBytes == nil then return nil, "tracked B+0xB0 unreadable" end
        backref = decodeU64(backrefBytes, 1)
        if backref == nil then return nil, "tracked B+0xB0 malformed" end
    end
    local nativeBackrefBytes, nativeBackref
    if nativeBlockBase ~= nil then
        if nativeBlockBase == blockBase then
            nativeBackrefBytes = backrefBytes
            nativeBackref = backref
        else
            nativeBackrefBytes = safeReadArray(
                nativeBlockBase + TARGET_BACKREFERENCE_OFFSET, 8, true)
            if nativeBackrefBytes == nil then
                return nil, "native B+0xB0 unreadable"
            end
            nativeBackref = decodeU64(nativeBackrefBytes, 1)
            if nativeBackref == nil then
                return nil, "native B+0xB0 malformed"
            end
        end
    end

    local descriptorAfter = safeReadArray(
        before.wpnBase + TRAIL_DESCRIPTOR_OFFSET,
        TRAIL_DESCRIPTOR_BYTES, true)
    local tableAfter = safeReadArray(
        before.tableAddress + TABLE_FOCUS_OFFSET,
        TABLE_FOCUS_BYTES, true)
    local recordAfter = recordPointer ~= 0 and safeReadArray(
        recordPointer, CONFIG.RECORD_BYTES, true) or nil
    local backrefAfter = blockBase ~= nil and safeReadArray(
        blockBase + TARGET_BACKREFERENCE_OFFSET, 8, true) or nil
    local nativeBackrefAfter = nil
    if nativeBlockBase ~= nil then
        if nativeBlockBase == blockBase then
            nativeBackrefAfter = backrefAfter
        else
            nativeBackrefAfter = safeReadArray(
                nativeBlockBase + TARGET_BACKREFERENCE_OFFSET, 8, true)
        end
    end
    local animationAfter = safeReadByte(before.sora + ANIMATION_OFFSET, true)
    local after, afterReason = resolveExactRoute()
    if after == nil then
        return nil, "route disappeared during double-read: " .. tostring(afterReason)
    end
    if coreRouteKey(before) ~= coreRouteKey(after) then
        return nil, "core Sora/table/MENV/WPN route changed during double-read"
    end
    for index = 0, POINTER_BANK_COUNT - 1 do
        if relevant[index] ~= nil
            and before.banks[index] ~= after.banks[index] then
            return nil, string.format(
                "referenced pointer bank %d changed during double-read", index)
        end
    end
    if animation ~= animationAfter then
        return nil, "animation changed during double-read"
    end
    if not sameBytes(descriptor, descriptorAfter)
        or not sameBytes(tableFocus, tableAfter) then
        return nil, "descriptor/table focus changed during double-read"
    end
    if recordPointer ~= 0 and not sameBytes(recordBytes, recordAfter) then
        return nil, "registration record changed during double-read"
    end
    if blockBase ~= nil and not sameBytes(backrefBytes, backrefAfter) then
        return nil, "B+0xB0 changed during double-read"
    end
    if nativeBlockBase ~= nil
        and not sameBytes(nativeBackrefBytes, nativeBackrefAfter) then
        return nil, "native B+0xB0 changed during double-read"
    end

    local unusedChanges = {}
    for index = 0, POINTER_BANK_COUNT - 1 do
        if relevant[index] == nil
            and before.banks[index] ~= after.banks[index] then
            unusedChanges[#unusedChanges + 1] = index
        end
    end
    -- Commit a between-callback B rebase only after every referenced bank and
    -- all focus bytes/backlinks passed the full double-read.  The native and
    -- observation roles may share one provenance table, so commit by table
    -- identity at most once.
    local committed = {}
    for _, update in pairs({ native = nativeBlockUpdate, observation = observationBlockUpdate }) do
        if update ~= nil and not committed[update.provenance] then
            local provenance = update.provenance
            emit(string.format(
                "%s COMPRESSED-BANK REBASE bank=%d encoded=%s previous_bank_base=%s current_bank_base=%s previous_B=%s current_B=%s snapshot_commit=true",
                update.role, provenance.bankIndex,
                valueText(provenance.encoded),
                pointerText(provenance.bankBase),
                pointerText(update.bankBase),
                pointerText(provenance.address),
                pointerText(update.address)), false)
            provenance.bankBase = update.bankBase
            provenance.address = update.address
            provenance.rebaseCount = (provenance.rebaseCount or 0) + 1
            committed[provenance] = true
        end
    end
    return {
        route = before,
        animation = animation,
        descriptor = descriptor,
        runtimeKey = runtimeKey,
        runtimeTarget = runtimeTarget, runtimeMode=runtimeMode,
        tableFocus = tableFocus,
        recordPointer = recordPointer,
        recordBytes = recordBytes,
        layout = layout,
        blockBase = blockBase,
        backref = backref,
        nativeBlockBase = nativeBlockBase,
        nativeBackref = nativeBackref,
        relevantSet = bankScopeSet(relevant),
        relevantScope = bankScopeText(relevant, before.banks),
        unusedChanges = unusedChanges,
    }, nil
end

local function copyBankSet(source)
    local result = {}
    for index = 0, POINTER_BANK_COUNT - 1 do
        if source and source[index] then result[index] = true end
    end
    return result
end

local function indexList(indices)
    local values = {}
    for _, index in ipairs(indices or {}) do values[#values + 1] = tostring(index) end
    return #values > 0 and table.concat(values, ",") or "<none>"
end

local function observeBankScope(snapshot)
    local banks = snapshot.route.banks
    local relevant = snapshot.relevantSet or {}
    if R.lastBanks ~= nil then
        local unused, used = {}, {}
        for index = 0, POINTER_BANK_COUNT - 1 do
            if banks[index] ~= R.lastBanks[index] then
                if relevant[index] or (R.lastRelevantBanks
                    and R.lastRelevantBanks[index]) then
                    used[#used + 1] = index
                    R.relevantBankChanges = R.relevantBankChanges + 1
                else
                    unused[#unused + 1] = index
                    R.ignoredUnusedBankChanges =
                        R.ignoredUnusedBankChanges + 1
                end
            end
        end
        if #unused > 0 then
            emit("IGNORED UNUSED-BANK CHURN indices=" .. indexList(unused), false)
        end
        if #used > 0 then
            emit("REFERENCED-BANK REBASE between callbacks indices="
                .. indexList(used) .. " current snapshot resolved independently", false)
        end
    end
    if #(snapshot.unusedChanges or {}) > 0 then
        R.ignoredUnusedBankChanges = R.ignoredUnusedBankChanges
            + #snapshot.unusedChanges
        emit("IGNORED UNUSED-BANK CHURN within double-read indices="
            .. indexList(snapshot.unusedChanges), false)
    end
    if snapshot.relevantScope ~= R.lastRelevantScope then
        emit("RELEVANT BANK SCOPE: " .. snapshot.relevantScope, false)
        R.lastRelevantScope = snapshot.relevantScope
    end
    R.lastBanks = {}
    for index = 0, POINTER_BANK_COUNT - 1 do R.lastBanks[index] = banks[index] end
    R.lastRelevantBanks = copyBankSet(relevant)
end

local function validateFreshNativeAsset(snapshot)
    for index = 1, #EXPECTED_FRESH_DESCRIPTOR do
        if snapshot.descriptor[index] ~= EXPECTED_FRESH_DESCRIPTOR[index] then
            return false, string.format(
                "fresh descriptor mismatch at WPN+0x%X expected=%02X actual=%02X",
                TRAIL_DESCRIPTOR_OFFSET + index - 1,
                EXPECTED_FRESH_DESCRIPTOR[index],
                snapshot.descriptor[index] or 0)
        end
    end
    if snapshot.runtimeKey ~= 0 then
        return false, "COLD_BASELINE_ALREADY_INITIALIZED: WPN+0x42F8 is nonzero; fully restart KH1FM"
    end
    local function rawQword(offset)
        local index = offset - TABLE_FOCUS_OFFSET + 1
        return decodeU32(snapshot.tableFocus, index) or 0,
            decodeU32(snapshot.tableFocus, index + 4) or 0
    end
    local t28l, t28h = rawQword(0x28)
    local t30l, t30h = rawQword(0x30)
    local t38l, t38h = rawQword(0x38)
    local t40l, t40h = rawQword(0x40)
    local t48l, t48h = rawQword(0x48)
    if t28l ~= 0 or t28h ~= 0
        or t30l ~= 0 or t30h ~= 0
        or t38l ~= 0xFFFFFFFF or t38h ~= 0
        or t40l ~= 0 or t40h ~= 0
        or t48l ~= 0 or t48h ~= 0 then
        return false, string.format(
            "COLD_BASELINE_ALREADY_INITIALIZED: table qwords +28=%s:%s +30=%s:%s +38=%s:%s +40=%s:%s +48=%s:%s",
            valueText(t28h), valueText(t28l), valueText(t30h),
            valueText(t30l), valueText(t38h), valueText(t38l),
            valueText(t40h), valueText(t40l), valueText(t48h),
            valueText(t48l))
    end
    local effectCount = safeReadInt(snapshot.route.wpnBase + 0x268, true)
    local fifthRelative = safeReadInt(snapshot.route.wpnBase + 0x27C, true)
    local nextCount = safeReadInt(snapshot.route.wpnBase + 0x280, true)
    local nextRelative = safeReadInt(snapshot.route.wpnBase + 0x284, true)
    if effectCount ~= 5 or fifthRelative ~= 0x8320
        or nextCount ~= 7 or nextRelative ~= 0x9390
        or 0x220 + fifthRelative ~= EFFECT_BLOCK_OFFSET
        or 0x220 + nextRelative ~= 0x95B0 then
        return false, "native MainFile effect-list boundary mismatch"
    end
    local pixels = safeReadArray(snapshot.route.wpnBase + TRAIL_PIXEL_OFFSET,
        TRAIL_PIXEL_BYTES, true)
    local clut = safeReadArray(snapshot.route.wpnBase + TRAIL_CLUT_OFFSET,
        TRAIL_CLUT_BYTES, true)
    if pixels == nil or clut == nil then
        return false, "native trail pixel/CLUT bytes unreadable"
    end
    local pixelHash, pixelSum = checksum33(pixels)
    local clutHash, clutSum = checksum33(clut)
    if pixelHash ~= EXPECTED_TRAIL_PIXEL_CHECKSUM33
        or pixelSum ~= EXPECTED_TRAIL_PIXEL_SUM
        or clutHash ~= EXPECTED_TRAIL_CLUT_CHECKSUM33
        or clutSum ~= EXPECTED_TRAIL_CLUT_SUM then
        return false, string.format(
            "native trail asset fingerprint mismatch pixels=%s CLUT=%s",
            fingerprint(pixels), fingerprint(clut))
    end
    return true, string.format(
        "fresh_descriptor_exact=true runtime_key_zero=true table_cold=true pixels=%s CLUT=%s",
        fingerprint(pixels), fingerprint(clut))
end

local function validateImmutableNativeAsset(snapshot)
    if snapshot == nil then return false, "no terminal coherent snapshot" end
    for index = 1, #EXPECTED_FRESH_DESCRIPTOR do
        if not MUTABLE_DESCRIPTOR_INDEX[index]
            and snapshot.descriptor[index] ~= EXPECTED_FRESH_DESCRIPTOR[index] then
            return false, string.format(
                "immutable descriptor mismatch at WPN+0x%X",
                TRAIL_DESCRIPTOR_OFFSET + index - 1)
        end
    end
    local effectCount = safeReadInt(snapshot.route.wpnBase + 0x268, true)
    local fifthRelative = safeReadInt(snapshot.route.wpnBase + 0x27C, true)
    local nextCount = safeReadInt(snapshot.route.wpnBase + 0x280, true)
    local nextRelative = safeReadInt(snapshot.route.wpnBase + 0x284, true)
    if effectCount ~= 5 or fifthRelative ~= 0x8320
        or nextCount ~= 7 or nextRelative ~= 0x9390 then
        return false, "native MainFile effect-list boundaries changed"
    end
    local pixels = safeReadArray(snapshot.route.wpnBase + TRAIL_PIXEL_OFFSET,
        TRAIL_PIXEL_BYTES, true)
    local clut = safeReadArray(snapshot.route.wpnBase + TRAIL_CLUT_OFFSET,
        TRAIL_CLUT_BYTES, true)
    if pixels == nil or clut == nil then
        return false, "native trail pixel/CLUT bytes became unreadable"
    end
    local pixelHash, pixelSum = checksum33(pixels)
    local clutHash, clutSum = checksum33(clut)
    if pixelHash ~= EXPECTED_TRAIL_PIXEL_CHECKSUM33
        or pixelSum ~= EXPECTED_TRAIL_PIXEL_SUM
        or clutHash ~= EXPECTED_TRAIL_CLUT_CHECKSUM33
        or clutSum ~= EXPECTED_TRAIL_CLUT_SUM then
        return false, "native trail pixel/CLUT identity changed"
    end
    return true, string.format(
        "pixels=%08X/%08X CLUT=%08X/%08X static_descriptor_bytes=26/26",
        pixelHash, pixelSum, clutHash, clutSum)
end

local function exactSourceTuple(record)
    return record ~= nil and record.effectId == CONFIG.EFFECT_ID
        and record.flags == CONFIG.EFFECT_FLAGS
        and record.handleClass == CONFIG.HANDLE_CLASS
        and record.owner == CONFIG.EFFECT_OWNER
end

local function parseQueueRecord(address, index, bytes)
    if bytes == nil or #bytes ~= QUEUE_ENTRY_SIZE then return nil end
    return {
        address = address,
        index = index,
        bytes = bytes,
        effectId = decodeU32(bytes, ENTRY_EFFECT_ID + 1),
        vector = decodeU64(bytes, ENTRY_VECTOR + 1) or 0,
        flags = decodeU32(bytes, ENTRY_FLAGS + 1),
        handleClass = decodeU32(bytes, ENTRY_HANDLE_CLASS + 1),
        owner = decodeU32(bytes, ENTRY_OWNER + 1),
        active = decodeU32(bytes, ENTRY_ACTIVE + 1),
    }
end

local function captureQueue()
    local count = safeReadInt(QUEUE_COUNT_RVA, false)
    local base = safeReadLong(QUEUE_POINTER_RVA, false)
    local result = { coherent = false, count = count or 0, base = base or 0,
        exact = {}, records = {}, reason = "queue header invalid" }
    if count == nil or count > CONFIG.MAX_QUEUE_ENTRIES then return result end
    if base == nil or (count > 0 and not plausiblePointer(base)) then return result end
    for index = 0, count - 1 do
        local address = base + index * QUEUE_ENTRY_SIZE
        local bytes = safeReadArray(address, QUEUE_ENTRY_SIZE, true)
        local record = parseQueueRecord(address, index, bytes)
        if record == nil then result.reason = "queue slot unreadable" return result end
        if exactSourceTuple(record) then
            record.vectorStatus = "POINTER_IMPLAUSIBLE"
            if plausiblePointer(record.vector) then
                record.vectorBytes = safeReadArray(record.vector, 16, true)
                record.position = vector4(record.vector)
                local vectorAfter = safeReadArray(record.vector, 16, true)
                local positionAfter = vector4(record.vector)
                if record.vectorBytes == nil and vectorAfter == nil then
                    record.vectorStatus = "VECTOR_UNREADABLE"
                elseif not sameBytes(record.vectorBytes, vectorAfter) then
                    result.reason = "source vector changed during double-read" return result
                elseif record.position == nil and positionAfter == nil then
                    record.vectorStatus = "VECTOR_NONFINITE_OR_OUT_OF_BOUNDS"
                elseif record.position == nil or positionAfter == nil then
                    result.reason = "source float reads changed" return result
                else
                    for n = 1, 4 do
                        if record.position[n] ~= positionAfter[n] then
                            result.reason = "source float reads changed" return result
                        end
                    end
                    record.vectorStatus = math.abs(record.position[4] - 2.0)
                        <= POSITION_TOLERANCE and "VALID_W2" or "W_NOT_2"
                end
            end
            record.vectorValid = record.vectorStatus == "VALID_W2"
            result.exact[#result.exact + 1] = record
        end
        local after = safeReadArray(address, QUEUE_ENTRY_SIZE, true)
        if not sameBytes(bytes, after) then
            result.reason = "queue slot changed during double-read" return result
        end
        result.records[#result.records + 1] = record
    end
    result.coherent = safeReadInt(QUEUE_COUNT_RVA, false) == count
        and safeReadLong(QUEUE_POINTER_RVA, false) == base
    result.reason = result.coherent and nil or "queue header changed"
    return result
end

local function captureRenderer()
    local count = safeReadInt(RENDERER_COUNT_RVA, false)
    local head = safeReadLong(RENDERER_HEAD_RVA, false)
    local snapshot = {
        coherent = false, count = count or 0, head = head or 0,
        exact = {}, nodes = {},
    }
    if count == nil or count > CONFIG.MAX_RENDERER_NODES then return snapshot end
    if count == 0 then
        local countAfter = safeReadInt(RENDERER_COUNT_RVA, false)
        local headAfter = safeReadLong(RENDERER_HEAD_RVA, false)
        snapshot.coherent = head ~= nil and head == 0
            and countAfter == count and headAfter ~= nil
            and headAfter == head
        return snapshot
    end
    if not plausiblePointer(head) then return snapshot end
    local address = head
    local visited = {}
    while plausiblePointer(address) and not visited[address]
        and #snapshot.nodes < CONFIG.MAX_RENDERER_NODES do
        visited[address] = true
        local bytes = safeReadArray(address, 0x40, true)
        local bytesAfter = safeReadArray(address, 0x40, true)
        if bytes == nil or not sameBytes(bytes, bytesAfter) then
            snapshot.reason = "renderer node unreadable/unstable" return snapshot
        end
        local node = {
            address = address,
            next = decodeU64(bytes, NODE_NEXT + 1) or 0,
            handle = decodeU32(bytes, NODE_HANDLE + 1),
            descriptor = decodeU64(bytes, NODE_DESCRIPTOR + 1) or 0,
            effectId = decodeU32(bytes, NODE_EFFECT_ID + 1),
            owner = decodeU32(bytes, NODE_OWNER + 1),
            active = decodeU32(bytes, NODE_ACTIVE + 1),
        }
        snapshot.nodes[#snapshot.nodes + 1] = node
        if node.effectId == CONFIG.EFFECT_ID
            and node.owner == CONFIG.EFFECT_OWNER
            and node.active ~= nil and node.active ~= 0 then
            snapshot.exact[#snapshot.exact + 1] = node
        end
        address = node.next
    end
    snapshot.coherent = address == 0 and #snapshot.nodes == count
        and safeReadInt(RENDERER_COUNT_RVA, false) == count
        and safeReadLong(RENDERER_HEAD_RVA, false) == head
    return snapshot
end

local function newPhase(name)
    return {
        name = name,
        frames = 0,
        rendererSeen = false,
        rendererRetired = false,
        rendererFrames = 0,
        rendererBirthFrame = nil,
        rendererRetireFrame = nil,
        rendererNode = nil,
        rendererHandle = nil,
        liveOverlapSamples = 0,
        liveOverlapFirstFrame = nil,
        liveOverlapLastFrame = nil,
        recordSeen = false,
        recordRetired = false,
        recordAddress = nil,
        recordBirthFrame = nil,
        recordRetireFrame = nil,
        recordLiveSamples = 0,
        identity = nil,
        poolOrigin = nil,
        blockBase = nil,
        blockEncoded = nil,
        blockBankIndex = nil,
        blockRebases = 0,
        canonicalLinkSamples = 0,
        ownerLinkSamples = 0,
        aliasSamples = 0,
        exactBackrefSamples = 0,
        state14First = nil,
        state14Final = nil,
        state14Last = nil,
        state14TransitionFrame = nil,
        state14Transitions = 0,
        state14PatternValid = true,
        clearObserved = false,
        clearFrame = nil,
        deviations = {},
        extraRecordBirths = 0,
        unpublishedBackrefSamples = 0,
        firstUnpublishedBackrefFrame = nil,
        firstUnpublishedBackref = nil,
    }
end

local function noteDeviation(phase, text)
    if #phase.deviations < 32 then phase.deviations[#phase.deviations + 1] = text end
end

local function observeRenderer(phase, renderer, frame)
    local count = #(renderer.exact or {})
    if count > 1 then return false, phase.name .. " has multiple exact renderers" end
    if count == 1 then
        local node = renderer.exact[1]
        if not phase.rendererSeen then
            phase.rendererSeen = true
            phase.rendererBirthFrame = frame
            phase.rendererNode = node.address
            phase.rendererHandle = node.handle
            emit(string.format(
                "%s AUDIO-SIDE RENDERER BIRTH frame=%d node=%s handle=%s descriptor=%s",
                phase.name, frame, pointerText(node.address),
                valueText(node.handle), pointerText(node.descriptor)), true)
        elseif phase.rendererRetired then
            return false, phase.name .. " exact renderer rebirthed after retirement"
        elseif node.address ~= phase.rendererNode
            or node.handle ~= phase.rendererHandle then
            return false, phase.name .. " exact renderer lineage changed while live"
        end
        phase.rendererFrames = phase.rendererFrames + 1
    elseif phase.rendererSeen and not phase.rendererRetired then
        phase.rendererRetired = true
        phase.rendererRetireFrame = frame
        emit(string.format("%s AUDIO-SIDE RENDERER RETIRE frame=%d live_samples=%d",
            phase.name, frame, phase.rendererFrames), true)
    end
    return true, nil
end

local function observeRegistration(phase, snapshot, frame)
    local pointer = snapshot.recordPointer
    if pointer ~= 0 then
        local layout = snapshot.layout
        if layout == nil then return false, phase.name .. " live record has no layout" end
        if not phase.recordSeen then
            phase.recordSeen = true
            phase.recordAddress = pointer
            phase.recordBirthFrame = frame
            phase.identity = layout.identity
            phase.poolOrigin = layout.poolOrigin
            phase.blockBase = layout.blockBase
            local provenance, provenanceReason = blockProvenance(
                layout, snapshot.route)
            if provenance == nil then
                return false, phase.name .. " B provenance failed: "
                    .. tostring(provenanceReason)
            end
            if phase.name == "FIRST" then
                if R.nativeBlockProvenance ~= nil then
                    return false, "first-swing B provenance was already bound"
                end
                R.nativeBlockProvenance = provenance
            end
            phase.blockEncoded = provenance.encoded
            phase.blockBankIndex = provenance.bankIndex
            R.observationBlockProvenance = provenance
            emit(string.format(
                "%s REGISTRATION BIRTH frame=%d record=%s identity=%s pool_origin=%s B=%s B_encoded=%s B_bank=%d B_bank_base=%s B_plus_B0=%s",
                phase.name, frame, pointerText(pointer),
                valueText(layout.identity), pointerText(layout.poolOrigin),
                pointerText(layout.blockBase), valueText(provenance.encoded),
                provenance.bankIndex, pointerText(provenance.bankBase),
                pointerText(snapshot.backref)), true)
        elseif phase.recordRetired then
            phase.extraRecordBirths = phase.extraRecordBirths + 1
            return false, phase.name .. " table+0x28 record rebirthed after retirement"
        elseif pointer ~= phase.recordAddress then
            return false, phase.name .. " table+0x28 record address changed while live"
        end
        local currentBlockBank = compressedBankIndex(layout.encodedBase)
        if layout.encodedBase ~= phase.blockEncoded
            or currentBlockBank ~= phase.blockBankIndex
            or layout.identity ~= phase.identity
            or layout.poolOrigin ~= phase.poolOrigin then
            return false, phase.name
                .. " record identity/pool/compressed-B provenance changed while live"
        end
        if layout.blockBase ~= phase.blockBase then
            emit(string.format(
                "%s LIVE B REBASE frame=%d encoded=%s bank=%d previous_B=%s current_B=%s",
                phase.name, frame, valueText(phase.blockEncoded),
                phase.blockBankIndex, pointerText(phase.blockBase),
                pointerText(layout.blockBase)), false)
            phase.blockBase = layout.blockBase
            phase.blockRebases = phase.blockRebases + 1
        end
        phase.recordLiveSamples = phase.recordLiveSamples + 1
        if phase.state14First == nil then
            phase.state14First = layout.state14
        end
        if layout.state14 ~= 1 and layout.state14 ~= 2 then
            phase.state14PatternValid = false
            noteDeviation(phase, "frame " .. tostring(frame)
                .. " record+0x14 unexpected=" .. valueText(layout.state14))
        end
        if phase.state14Last ~= nil
            and layout.state14 ~= phase.state14Last then
            phase.state14Transitions = phase.state14Transitions + 1
            if phase.state14TransitionFrame == nil then
                phase.state14TransitionFrame = frame
            end
            if phase.state14Last ~= 1 or layout.state14 ~= 2
                or phase.state14Transitions > 1 then
                phase.state14PatternValid = false
                noteDeviation(phase, string.format(
                    "frame %d record+0x14 noncanonical transition %s->%s count=%d",
                    frame, valueText(phase.state14Last),
                    valueText(layout.state14), phase.state14Transitions))
            end
        end
        phase.state14Last = layout.state14
        phase.state14Final = layout.state14
        if layout.canonicalLinks then
            phase.canonicalLinkSamples = phase.canonicalLinkSamples + 1
        else
            noteDeviation(phase, "frame " .. tostring(frame)
                .. " link deviations=" .. table.concat(layout.deviations, ";"))
        end
        if layout.ownerCanonical then
            phase.ownerLinkSamples = phase.ownerLinkSamples + 1
        else
            noteDeviation(phase, "frame " .. tostring(frame)
                .. " owner=" .. pointerText(layout.ownerTarget)
                .. " expected=" .. pointerText(layout.ownerExpected))
        end
        if layout.viewsAlias and layout.aliasCanonical then
            phase.aliasSamples = phase.aliasSamples + 1
        else
            noteDeviation(phase, "frame " .. tostring(frame)
                .. " derived alias mismatch cell24=" .. pointerText(layout.cell24)
                .. " cell28=" .. pointerText(layout.cell28))
        end
        if snapshot.backref == pointer then
            phase.exactBackrefSamples = phase.exactBackrefSamples + 1
        else
            noteDeviation(phase, "frame " .. tostring(frame)
                .. " B+0xB0=" .. pointerText(snapshot.backref)
                .. " record=" .. pointerText(pointer))
        end
    elseif phase.recordSeen then
        if not phase.recordRetired then
            phase.recordRetired = true
            phase.recordRetireFrame = frame
            emit(string.format("%s REGISTRATION RETIRE frame=%d live_samples=%d B_plus_B0=%s",
                phase.name, frame, phase.recordLiveSamples,
                pointerText(snapshot.backref)), true)
        end
        if snapshot.backref == 0 and not phase.clearObserved then
            phase.clearObserved = true
            phase.clearFrame = frame
            emit(string.format("%s BACKREFERENCE CLEAR frame=%d B=%s",
                phase.name, frame, pointerText(phase.blockBase)), true)
        end
    elseif snapshot.backref ~= nil and snapshot.backref ~= 0 then
        phase.unpublishedBackrefSamples = phase.unpublishedBackrefSamples + 1
        if phase.firstUnpublishedBackrefFrame == nil then
            phase.firstUnpublishedBackrefFrame = frame
            phase.firstUnpublishedBackref = snapshot.backref
            emit(string.format(
                "%s UNPUBLISHED TRACKED-B BACKREFERENCE frame=%d table28=0 B_plus_B0=%s",
                phase.name, frame, pointerText(snapshot.backref)), true)
        end
    end
    return true, nil
end

local function observeLiveOverlap(phase, snapshot, renderer, frame)
    if snapshot.recordPointer ~= 0 and #(renderer.exact or {}) == 1 then
        phase.liveOverlapSamples = phase.liveOverlapSamples + 1
        phase.liveOverlapFirstFrame = phase.liveOverlapFirstFrame or frame
        phase.liveOverlapLastFrame = frame
    end
end

local function phaseStructurallyComplete(phase)
    return phase ~= nil
        and phase.recordSeen
        and phase.recordRetired
        and phase.clearObserved
        and phase.recordLiveSamples > 0
        and phase.canonicalLinkSamples == phase.recordLiveSamples
        and phase.ownerLinkSamples == phase.recordLiveSamples
        and phase.aliasSamples == phase.recordLiveSamples
        and phase.exactBackrefSamples == phase.recordLiveSamples
        and (phase.name ~= "FIRST" or phase.liveOverlapSamples > 0)
        and phase.state14PatternValid
        and phase.state14First == 1
        and phase.state14Final == 2
        and phase.state14Transitions == 1
end

local function phaseSummary(phase)
    if phase == nil then return "<absent>" end
    return string.format(
        "audio_renderer_seen=%s audio_renderer_birth=%s audio_renderer_retire=%s audio_renderer_samples=%d record_seen=%s record=%s identity=%s pool=%s B_last_live=%s B_encoded=%s B_bank=%s B_live_rebases=%d record_birth=%s record_retire=%s live_samples=%d audio_renderer_record_overlap_samples=%d overlap_first=%s overlap_last=%s canonical_links=%d owner_links=%d aliases=%d exact_backrefs=%d state14_first=%s state14_final=%s state14_transitions=%d state14_transition_frame=%s state14_pattern_valid=%s clear=%s clear_frame=%s unpublished_backref_samples=%d first_unpublished_frame=%s first_unpublished_value=%s structural_complete=%s deviations=%d",
        boolText(phase.rendererSeen), tostring(phase.rendererBirthFrame),
        tostring(phase.rendererRetireFrame), phase.rendererFrames,
        boolText(phase.recordSeen), pointerText(phase.recordAddress),
        valueText(phase.identity), pointerText(phase.poolOrigin),
        pointerText(phase.blockBase), valueText(phase.blockEncoded),
        tostring(phase.blockBankIndex), phase.blockRebases,
        tostring(phase.recordBirthFrame),
        tostring(phase.recordRetireFrame), phase.recordLiveSamples,
        phase.liveOverlapSamples, tostring(phase.liveOverlapFirstFrame),
        tostring(phase.liveOverlapLastFrame),
        phase.canonicalLinkSamples, phase.ownerLinkSamples,
        phase.aliasSamples, phase.exactBackrefSamples,
        valueText(phase.state14First), valueText(phase.state14Final),
        phase.state14Transitions, tostring(phase.state14TransitionFrame),
        boolText(phase.state14PatternValid),
        boolText(phase.clearObserved), tostring(phase.clearFrame),
        phase.unpublishedBackrefSamples,
        tostring(phase.firstUnpublishedBackrefFrame),
        pointerText(phase.firstUnpublishedBackref),
        boolText(phaseStructurallyComplete(phase)), #phase.deviations)
end


local function limitedLine(kind, text)
    local countKey = kind == "visual" and "visualLines" or "matchLines"
    local suppressedKey = kind == "visual" and "visualLinesSuppressed" or "matchLinesSuppressed"
    local cap = kind == "visual" and CONFIG.MAX_VISUAL_LINES or CONFIG.MAX_MATCH_LINES
    if R[countKey] >= cap then R[suppressedKey] = R[suppressedKey] + 1 return end
    R[countKey] = R[countKey] + 1
    emit(text, false)
end

local function compactQueue(queue)
    local rows = {}
    for _, rec in ipairs(queue.records or {}) do
        rows[#rows + 1] = {
            address = rec.address, index = rec.index, effectId = rec.effectId,
            unknown04 = decodeU32(rec.bytes, 5), vector = rec.vector,
            flags = rec.flags, handleClass = rec.handleClass,
            owner = rec.owner, active = rec.active,
            raw = exactBytesKey(rec.bytes), body = exactBytesKey(nonActiveBytes(rec.bytes)),
        }
    end
    return rows
end

local function stableWitness(address, count)
    if address == nil or address == 0 then return {status = "NOT_AVAILABLE", address = 0} end
    if not plausiblePointer(address) then return {status = "POINTER_IMPLAUSIBLE", address = address} end
    local a = safeReadArray(address, count, true)
    local b = safeReadArray(address, count, true)
    if a == nil or b == nil then return {status = "UNREADABLE", address = address} end
    if not sameBytes(a, b) then return {status = "DOUBLE_READ_CHANGED", address = address} end
    return {status = "STABLE", address = address, bytes = copyBytes(a), hash = fingerprint(a)}
end

local function captureVisualWitnesses(snapshot)
    local t48 = decodeU64(snapshot.tableFocus, 0x48 - TABLE_FOCUS_OFFSET + 1) or 0
    local result = {
        block = stableWitness(snapshot.blockBase, 0x100),
        table48 = stableWitness(t48, 0x80),
        runtime = stableWitness(snapshot.runtimeTarget, 0x100),
        effect = stableWitness(snapshot.route.wpnBase + EFFECT_BLOCK_OFFSET, 0xD60),
    }
    -- These larger witnesses are separate observations, not an atomic
    -- engine snapshot. Mark their attribution unavailable if their proven
    -- pointer source or any referenced bank changes while they are read.
    local desc = safeReadArray(snapshot.route.wpnBase + TRAIL_DESCRIPTOR_OFFSET, TRAIL_DESCRIPTOR_BYTES, true)
    local tableNow = safeReadArray(snapshot.route.tableAddress + TABLE_FOCUS_OFFSET, TABLE_FOCUS_BYTES, true)
    local banks = readBankBases()
    local attributionOK = sameBytes(desc, snapshot.descriptor) and sameBytes(tableNow, snapshot.tableFocus)
    for index = 0, POINTER_BANK_COUNT - 1 do
        if snapshot.relevantSet[index] and banks[index] ~= snapshot.route.banks[index] then attributionOK = false end
    end
    if not attributionOK then
        for _, witness in pairs(result) do
            witness.status = "FOCUS_OR_REFERENCED_BANK_CHANGED"
            witness.bytes = nil; witness.hash = nil
        end
    end
    return result
end

local function captureFastWitnesses(snapshot)
    local block={status="NOT_AVAILABLE"}
    if (R.geometry==nil or not R.geometry.bound) and snapshot.layout and snapshot.layout.state14==1 then
        block=stableWitness(snapshot.blockBase,0x100)
    end
    return {block=block,table48={status="NOT_AVAILABLE"},runtime={status="NOT_AVAILABLE"},effect={status="NOT_AVAILABLE"}}
end
local function makeSample(snapshot, queue, renderer)
    local tableFocus = snapshot.tableFocus
    local banks = {}
    for i = 0, POINTER_BANK_COUNT - 1 do banks[i] = snapshot.route.banks[i] end
    return {
        tick = R.tick, animation = snapshot.animation,
        queueBase = queue.base, queueCount = queue.count, rows = compactQueue(queue),
        banks = banks, descriptor = copyBytes(snapshot.descriptor),
        tableFocus = copyBytes(tableFocus), recordPointer = snapshot.recordPointer,
        backref = snapshot.backref, runtimeKey = snapshot.runtimeKey,
        runtimeTarget = snapshot.runtimeTarget, blockBase = snapshot.blockBase,
        ownerMain = decodeU64(tableFocus, 0x30 - TABLE_FOCUS_OFFSET + 1) or 0,
        selector = decodeU32(tableFocus, 0x38 - TABLE_FOCUS_OFFSET + 1),
        control40Low = decodeU32(tableFocus, 0x40 - TABLE_FOCUS_OFFSET + 1),
        control40High = decodeU32(tableFocus, 0x44 - TABLE_FOCUS_OFFSET + 1),
        table48 = decodeU64(tableFocus, 0x48 - TABLE_FOCUS_OFFSET + 1) or 0,
        audioCount = #(renderer.exact or {}),
        wpnBase = snapshot.route.wpnBase,
        witnesses = captureFastWitnesses(snapshot),
    }
end

local function ringPush(sample)
    R.preRing[#R.preRing + 1] = sample
    if #R.preRing > CONFIG.PRE_ENTRY_SAMPLES then table.remove(R.preRing, 1) end
end

local function witnessStatus(witness)
    return witness.status .. "/" .. tostring(witness.hash or "no_bytes")
end

local function observeVisual(phase, sample)
    local frame = sample.frame
    local old = phase.previousVisual
    for _, name in ipairs({"block", "table48", "runtime", "effect"}) do
        local w = sample.witnesses[name]
        if w.status ~= "STABLE" and w.status ~= "NOT_AVAILABLE" then
            phase.witnessGaps[name] = phase.witnessGaps[name] + 1
        end
    end
    if old ~= nil and (old.selector ~= sample.selector or old.ownerMain ~= sample.ownerMain
        or old.control40Low ~= sample.control40Low or old.control40High ~= sample.control40High
        or old.table48 ~= sample.table48 or old.runtimeKey ~= sample.runtimeKey) then
        emit(string.format("%s VISUAL ROUTE SCALAR CHANGE frame=%d owner30=%s->%s selector38=%s->%s control40=%s:%s->%s:%s cursor48=%s->%s runtime42F8=%s->%s table_raw48bytes=%s descriptor_raw32bytes=%s",
            phase.name, frame, pointerText(old.ownerMain), pointerText(sample.ownerMain),
            valueText(old.selector), valueText(sample.selector), valueText(old.control40High), valueText(old.control40Low),
            valueText(sample.control40High), valueText(sample.control40Low), pointerText(old.table48), pointerText(sample.table48),
            valueText(old.runtimeKey), valueText(sample.runtimeKey), exactBytesKey(sample.tableFocus), exactBytesKey(sample.descriptor)), false)
    end
    local checkpoints = frame <= 8 or frame == 43 or frame == 44 or frame == 79 or frame == CONFIG.DELAYED_SAMPLES
        or frame == phase.recordBirthFrame or frame == phase.recordRetireFrame
    if checkpoints then
        for _, name in ipairs({"block", "table48", "runtime"}) do
            local w = sample.witnesses[name]
            if w.status ~= "NOT_AVAILABLE" then
                limitedLine("visual", string.format("%s VISUAL WITNESS frame=%d domain=%s address=%s status=%s raw=%s optional_not_registration_gate=true",
                    phase.name, frame, name, pointerText(w.address), w.status, w.bytes and exactBytesKey(w.bytes) or "unavailable"))
            end
        end
    end
    local runtime = sample.witnesses.runtime
    local pixels = runtime.bytes and decodeU64(runtime.bytes, 0x81) or nil
    local rtPixels = pixels ~= nil and pixels == sample.wpnBase + TRAIL_PIXEL_OFFSET
    local firstTextureLink = rtPixels and phase.firstRuntimePixelLinkFrame == nil
    if firstTextureLink then phase.firstRuntimePixelLinkFrame = frame end
    if checkpoints or firstTextureLink then
        emit(string.format(
            "%s CALLBACK frame=%d tick=%d anim=%s queue_count=%d table28=%s owner30=%s selector38=%s control40=%s:%s cursor48=%s runtime42F8=%s runtime_target=%s runtime_plus80_pixels_exact=%s B=%s B_plusB0=%s audio_renderer_count=%d B_witness=%s cursor_witness=%s runtime_witness=%s effect_witness=%s",
            phase.name, frame, sample.tick, valueText(sample.animation), sample.queueCount,
            pointerText(sample.recordPointer), pointerText(sample.ownerMain), valueText(sample.selector),
            valueText(sample.control40High), valueText(sample.control40Low), pointerText(sample.table48),
            valueText(sample.runtimeKey), pointerText(sample.runtimeTarget), boolText(rtPixels),
            pointerText(sample.blockBase), pointerText(sample.backref), sample.audioCount,
            witnessStatus(sample.witnesses.block), witnessStatus(sample.witnesses.table48),
            witnessStatus(runtime), witnessStatus(sample.witnesses.effect)), false)
    end
    phase.previousVisual = sample
end

