        local a=safeReadArray(R.moduleBase+anchor.rva,#anchor.bytes,true)
        local b=safeReadArray(R.moduleBase+anchor.rva,#anchor.bytes,true)
        if not sameBytes(a,b) or not sameBytes(a,anchor.bytes) then return false,"V204 native code anchor mismatch at "..valueText(anchor.rva) end
    end
