local function maskSet(word, mask) return math.floor(word / mask) % 2 == 1 end
local function sameStaticDescriptor(a,b)
    if a==nil or b==nil or #a~=#b then return false end
    for i=1,#a do if not MUTABLE_DESCRIPTOR_INDEX[i] and a[i]~=b[i] then return false end end
