local baseFocus = captureRegistrationFocus
captureRegistrationFocus = function()
    local route, why = resolveExactRoute()
    if route == nil then return nil, why end
    local a = {safeReadArray(route.sora,4,true),safeReadArray(route.sora+0x1CC,4,true),safeReadArray(route.sora+0x374,4,true)}
    if a[1]==nil or a[2]==nil or a[3]==nil then return nil,"actor gate/predicate words unreadable" end
    local snapshot, focusWhy = baseFocus()
    if snapshot==nil then return nil,focusWhy end
    if coreRouteKey(route)~=coreRouteKey(snapshot.route) then return nil,"actor gate route changed" end
    local b = {safeReadArray(route.sora,4,true),safeReadArray(route.sora+0x1CC,4,true),safeReadArray(route.sora+0x374,4,true)}
    for i=1,3 do if not sameBytes(a[i],b[i]) then return nil,"actor gate/predicate changed around focus" end end
    snapshot.actorFlags=decodeU32(a[1],1); snapshot.actorEventFlags=decodeU32(a[2],1)
    snapshot.predicateWord=decodeU32(a[3],1)
