end
local C={stats={},programs={},targets={},savedParentArray=nil}
R.child=C
do
local ANCHORS=CODE_ANCHORS
local ROOT_SEEDS,CONTEXTS={},{}
local function hexBytes(bytes) return exactBytesKey(bytes) end
local function decodeU16(bytes, index)
    if bytes == nil or bytes[index] == nil or bytes[index + 1] == nil then return nil end
    return bytes[index] + bytes[index + 1] * 256
end

local function stableCode(rva, count)
    if rva < 0 or count < 1 or R.code.imageSize ~= nil and rva + count > R.code.imageSize then
        return nil, "code/header span outside image bounds"
    end
    local a = safeReadArray(R.moduleBase + rva, count, true)
    local b = safeReadArray(R.moduleBase + rva, count, true)
    if a == nil or b == nil then return nil, "code/header span unreadable" end
    if not sameBytes(a, b) then return nil, "code/header double-read changed" end
    return a
end

local function executableSection(rva, finishRva)
    for _, section in ipairs(R.code.sections) do
        if rva >= section.begin and (finishRva or rva + 1) <= section.finish then return section end
    end
    return nil
end

local function loadImageMetadata()
    local dos, why = stableCode(0, 0x40)
    if dos == nil then return false, why end
    if decodeU16(dos, 1) ~= 0x5A4D then return false, "loaded image has no MZ header" end
    local pe = decodeU32(dos, 0x3D)
    if pe == nil or pe < 0x40 or pe > 0x10000 then return false, "PE header offset out of bounds" end
    local nt, ntWhy = stableCode(pe, 24)
    if nt == nil then return false, ntWhy end
    if decodeU32(nt, 1) ~= 0x00004550 or decodeU16(nt, 5) ~= 0x8664 then
        return false, "loaded image is not AMD64 PE"
    end
    local sectionCount = decodeU16(nt, 7)
    local optionalSize = decodeU16(nt, 21)
    if sectionCount == nil or sectionCount < 1 or sectionCount > CONFIG.MAX_SECTIONS
        or optionalSize == nil or optionalSize < 0x90 or optionalSize > 0x1000 then
        return false, "section count/optional header size exceeds bounds"
    end
    local opt, optWhy = stableCode(pe + 24, optionalSize)
    if opt == nil then return false, optWhy end
    if decodeU16(opt, 1) ~= 0x20B or (decodeU32(opt, 0x6D) or 0) < 4 then
        return false, "PE32+ header/exception directory unavailable"
    end
    local size = decodeU32(opt, 0x39)
    if size == nil or size < pe + 24 + optionalSize + sectionCount * 40
        or size > CONFIG.MAX_IMAGE_BYTES then return false, "SizeOfImage out of bounds" end
    R.code.timestamp=decodeU32(nt,9)
    R.code.sectionAlignment=decodeU32(opt,0x21)
    R.code.headerSpans={{rva=0,bytes=dos},{rva=pe,bytes=nt},{rva=pe+24,bytes=opt}}
    R.code.imageSize = size
    R.code.exceptionRva = decodeU32(opt, 0x89)
    R.code.exceptionSize = decodeU32(opt, 0x8D)
    if R.code.exceptionRva == nil or R.code.exceptionRva == 0 or R.code.exceptionSize == nil
        or R.code.exceptionSize == 0 or R.code.exceptionSize % 12 ~= 0
        or R.code.exceptionSize / 12 > CONFIG.MAX_RUNTIME_FUNCTIONS
        or R.code.exceptionRva + R.code.exceptionSize > size then
        return false, "x64 exception table geometry exceeds bounds"
    end
    local headers, headerWhy = stableCode(pe + 24 + optionalSize, sectionCount * 40)
    if headers == nil then return false, headerWhy end
    R.code.headerSpans[#R.code.headerSpans+1]={rva=pe+24+optionalSize,bytes=headers}
    for n = 0, sectionCount - 1 do
        local i = n * 40 + 1
        local chars = {}
        for k = 0, 7 do if headers[i + k] == 0 then break end chars[#chars + 1] = string.char(headers[i + k]) end
        local name = table.concat(chars)
        local virtualSize = decodeU32(headers, i + 8)
        local rva = decodeU32(headers, i + 12)
        local rawSize = decodeU32(headers, i + 16)
        local flags = decodeU32(headers, i + 36)
        if math.floor(flags / 0x20000000) % 2 == 1 then
            local count = virtualSize ~= 0 and virtualSize or rawSize
            if count <= 0 or rva + count > size then return false, "executable section outside loaded image" end
            R.code.sections[#R.code.sections + 1] = {name = name, begin = rva, finish = rva + count, bytes = count, rawFinish=rva+rawSize, flags=flags}
            R.code.executableBytes = R.code.executableBytes + count
        end
    end
    table.sort(R.code.sections, function(a, b) return a.begin < b.begin end)
    if #R.code.sections == 0 or R.code.executableBytes > CONFIG.MAX_EXECUTABLE_BYTES then
        return false, "executable-section count/total byte cap failed"
    end
    for n = 2, #R.code.sections do
        if R.code.sections[n].begin < R.code.sections[n - 1].finish then return false, "executable sections overlap" end
    end
    emit(string.format("PE CODE METADATA PASS module_base=%s image_bytes=%d timestamp=%s executable_sections=%d executable_bytes=%d exception_rva=%s exception_bytes=%d runtime_rows=%d AMD64_PE32plus=true",
        pointerText(R.moduleBase), size, valueText(decodeU32(nt, 9)), #R.code.sections,
        R.code.executableBytes, valueText(R.code.exceptionRva), R.code.exceptionSize, R.code.exceptionSize / 12), true)
    for _, section in ipairs(R.code.sections) do
        emit(string.format("EXECUTABLE SECTION name=%s begin_rva=%s end_rva=%s bytes=%d",
            section.name, valueText(section.begin), valueText(section.finish), section.bytes), false)
    end
    R.stage = "code_exception"
    return true
end

local expectedPrograms={
    {object=0x5508B0,update=0x32AA30,draw=0},
    {object=0x550B30,update=0x32B2B0,draw=0},
    {object=0x550C70,update=0x32B940,draw=0},
    {object=0x553D80,update=0x33AEE0,draw=0x33AC50},
}
local function withinWpn(address,count,route)
    return type(address)=="number" and count>=0 and address>=route.wpnBase
        and address+count<=route.wpnBase+EXPECTED_WPN_SIZE
end
local function slice(bytes,offset,count)
    local result={} for i=1,count do result[i]=bytes[offset+i] end return result
end
local function signed32(value) return value>=0x80000000 and value-0x100000000 or value end
local function graphRead(g,address,count,role)
    if not plausiblePointer(address) or count<1 or count%1~=0 then return nil,"invalid "..role.." span" end
    if g.bytes+count>CONFIG.MAX_GRAPH_BYTES then return nil,"CAP: graph byte limit before "..role end
    local a=safeReadArray(address,count,true); local b=safeReadArray(address,count,true)
    if not sameBytes(a,b) then return nil,role.." unreadable or changed in double read" end
    g.bytes=g.bytes+count; g.spans[#g.spans+1]={address=address,bytes=a,role=role}
    return a
end
local function encodedAddress(g,key,count,role)
    if not isCompressedPointerValue(key) then return nil,role.." is not an explicitly encoded pointer" end
    local index=compressedBankIndex(key); local base=g.route.banks[index]
    local address=resolveCompressed(key,g.route.banks,false)
    if address==0 or not plausiblePointer(address) or address+count>base+POINTER_BANK_SIZE then return nil,role.." leaves a plausible aligned bank" end
    if g.banks[index]~=nil and g.banks[index]~=base then return nil,role.." bank changed within graph" end
    g.banks[index]=base
    return address
end
local function programRecord(g,key)
    if g.programs[key]~=nil then return g.programs[key] end
    local address,why=encodedAddress(g,key,CONFIG.PROGRAM_RECORD_WINDOW,"program object")
    if address==nil then return nil,why end
    if address<R.moduleBase or address+CONFIG.PROGRAM_RECORD_WINDOW>R.moduleBase+R.code.imageSize then return nil,"program object leaves the pinned executable image" end
    local bytes,readWhy=graphRead(g,address,CONFIG.PROGRAM_RECORD_WINDOW,"callback object")
    if bytes==nil then return nil,readWhy end
    local fields={}; local roles={[0x28]="PARENT_PRE_UPDATE_FIELD",[0x08]="CHILD_UPDATE_FIELD",[0x18]="CHILD_DRAW_FIELD",[0x20]="PARENT_INITIALIZER_FIELD",
        [0x30]="PARENT_UPDATE_FIELD",[0x38]="CHILD_SPAWN_FIELD",[0x40]="CHILD_RESET_FIELD",[0x48]="CHILD_RELEASE_FIELD"}
    for offset=0,CONFIG.PROGRAM_RECORD_WINDOW-8,8 do
        local value=decodeU64(bytes,offset+1); local rva=value and value-R.moduleBase or nil
        if plausiblePointer(value) and executableSection(rva)~=nil then
            fields[#fields+1]={offset=offset,value=value,rva=rva,role=roles[offset] or "EXECUTABLE_POINTER_CANDIDATE"}
        end
    end
    local record={key=key,address=address,bank=compressedBankIndex(key),base=g.route.banks[compressedBankIndex(key)],bytes=bytes,fields=fields}
    g.programs[key]=record
