end
local function definition(g,address)
    if g.definitions[address]~=nil then return g.definitions[address] end
    if not withinWpn(address,0x28,g.route) then return nil,"runtime definition header leaves native WPN" end
    local head,why=graphRead(g,address,0x28,"WPN child definition header")
    if head==nil then return nil,why end
    local count=decodeU16(head,0x27); local payload=decodeU32(head,0x21)
    if count>CONFIG.MAX_CHILD_PROPERTIES then return nil,"CAP: definition property count" end
    local width=0x28+count*0x10
    local childBytes=payload+count*8
    if payload<0xA0 or childBytes>CONFIG.MAX_CHILD_BYTES then return nil,"CAP: definition child allocation size" end
    if not withinWpn(address,width,g.route) then return nil,"child definition/property array leaves WPN" end
    local bytes,readWhy=graphRead(g,address,width,"WPN child definition/properties")
    if bytes==nil then return nil,readWhy end
    if not sameBytes(head,slice(bytes,0,0x28)) then return nil,"child definition changed around property reads" end
    local d={address=address,count=count,payload=payload,childBytes=childBytes,bytes=bytes,properties={}}
    for i=0,count-1 do
        local offset=0x28+i*0x10
        local key=decodeU32(bytes,offset+1)
        local program,programWhy=programRecord(g,key)
        if program==nil then return nil,programWhy end
        local stream=address+offset+signed32(decodeU32(bytes,offset+9))
        if not withinWpn(stream,4,g.route) then return nil,"definition property stream leaves WPN" end
        d.properties[#d.properties+1]={slot=i,key=key,program=program,stream=stream,offset=offset}
    end
    g.definitions[address]=d
    return d
end
local function captureChildGraph(snapshot,sample)
    local b=sample.witnesses.block.bytes
    if sample.witnesses.block.status~="STABLE" or b==nil then return nil,"stable parent witness unavailable" end
    if decodeU64(b,0xB1)~=snapshot.recordPointer or decodeU64(b,0xC1)~=snapshot.route.sora
        or decodeU64(b,0xA1)~=snapshot.route.wpnBase+0x3970
        or decodeU32(b,0x65)~=4 or decodeU64(b,0x81)~=snapshot.route.wpnBase+0x3BBC then
        return nil,"parent actor, backlink or V202 program binding differs"
    end
    local g={route=snapshot.route,parent=b,bytes=0,spans={},banks={},programs={},definitions={},rows={},nodes={},nodeSet={}}
    local parent,why=graphRead(g,snapshot.blockBase,0xE0,"parent")
    if parent==nil or not sameBytes(parent,slice(b,0,0xE0)) then return nil,why or "parent changed before graph" end
    local arrayAddress=decodeU64(parent,0x81)
    local array,arrayWhy=graphRead(g,arrayAddress,16,"parent program array")
    if array==nil then return nil,arrayWhy end
    g.arrayAddress=arrayAddress; g.arrayBytes=array
    for i,p in ipairs(expectedPrograms) do
        local record,programWhy=programRecord(g,decodeU32(array,(i-1)*4+1))
        local draw=p.draw==0 and 0 or R.moduleBase+p.draw
        if record==nil then return nil,programWhy end
        if record.address~=R.moduleBase+p.object or decodeU64(record.bytes,9)~=R.moduleBase+p.update
            or decodeU64(record.bytes,0x19)~=draw or decodeU64(record.bytes,0x21)~=0 then return nil,"V202 parent callback profile differs" end
    end
    local count=decodeU32(parent,0x69); local rowBase=decodeU64(parent,0x89)
    if count<1 or count>CONFIG.MAX_CHILD_GROUPS then return nil,"CAP: runtime group count" end
    local rows,rowWhy=graphRead(g,rowBase,count*0x18,"runtime child rows")
    if rows==nil then return nil,rowWhy end
    g.rowBase=rowBase; g.rowBytes=rows
    for i=0,count-1 do
