        local def,defWhy=definition(g,decodeU64(row,1))
        if def==nil then return nil,defWhy end
        local childCount=decodeU16(row,0x15); local head=decodeU64(row,9)
        if childCount>CONFIG.MAX_CHILD_NODES then return nil,"CAP: runtime child count" end
        if childCount==0 and head~=0 or childCount>0 and not plausiblePointer(head) then return nil,"runtime head/count inconsistent" end
        g.rows[#g.rows+1]={address=address,head=head,count=childCount,definition=def,bytes=row,captured=0,headSeen=head==0}
    end
    local key=decodeU32(parent,0x79)
    g.headKey=key
    while key~=0 do
        if #g.nodes>=CONFIG.MAX_CHILD_NODES then return nil,"CAP: linked child count" end
        local address,nodeWhy=encodedAddress(g,key,0xA0,"linked child")
        if address==nil then return nil,nodeWhy end
        if g.nodeSet[address] then return nil,"linked child cycle or duplicate address" end
        local head,headWhy=graphRead(g,address,0xA0,"child header")
        if head==nil then return nil,headWhy end
        local owner,ownerWhy=encodedAddress(g,decodeU32(head,9),0x18,"child owning runtime row")
        if owner==nil then return nil,ownerWhy end
        local index=(owner-rowBase)/0x18+1
        if index%1~=0 or index<1 or index>#g.rows then return nil,"child owner does not name a captured runtime row" end
        local row=g.rows[index]; local d=row.definition
        local bytes,bodyWhy=graphRead(g,address,d.childBytes,"child allocation and property cursors")
        if bytes==nil then return nil,bodyWhy end
        if not sameBytes(head,slice(bytes,0,0xA0)) then return nil,"child header changed around allocation capture" end
        local node={address=address,key=key,row=index-1,bytes=bytes,cursors={},drawGates={}}
        for i,p in ipairs(d.properties) do
            local cursor=decodeU64(bytes,d.payload+(i-1)*8+1)
            if not withinWpn(cursor,4,g.route) then return nil,"child property cursor leaves WPN" end
            local width=math.min(0x40,g.route.wpnBase+EXPECTED_WPN_SIZE-cursor)
            local data,dataWhy=graphRead(g,cursor,width,"child property cursor data")
            if data==nil then return nil,dataWhy end
            node.cursors[#node.cursors+1]={slot=i-1,address=cursor,bytes=data,key=p.key}
            if decodeU64(p.program.bytes,0x19)==R.moduleBase+0x33AC50 then
                local draw={slot=i-1,mesh=decodeU32(data,5),available=false,reason="CHANNEL_OFFSET_UNAVAILABLE"}
                local channelAddress=d.address+p.offset+signed32(decodeU32(d.bytes,p.offset+0x0D))
                if withinWpn(channelAddress,4,g.route) then
                    local channel,channelWhy=graphRead(g,channelAddress,4,"draw channel offset word")
