    for _,row in ipairs(g.rows) do
        if row.captured~=row.count or not row.headSeen then return nil,"runtime counts/head do not cover the linked children" end
    end
    for _,span in ipairs(g.spans) do
        if not sameBytes(span.bytes,safeReadArray(span.address,#span.bytes,true)) then return nil,"saved "..span.role.." changed around whole graph" end
    end
    local after,afterWhy=captureRegistrationFocus()
    if after==nil or coreRouteKey(after.route)~=coreRouteKey(snapshot.route) or after.recordPointer~=snapshot.recordPointer
        or after.blockBase~=snapshot.blockBase or after.backref~=snapshot.recordPointer or not sameBytes(after.recordBytes,snapshot.recordBytes) then
        return nil,"canonical focus changed around child graph: "..tostring(afterWhy)
    end
    for bank,base in pairs(g.banks) do
        if after.route.banks[bank]~=base then return nil,"referenced child/program bank changed around graph" end
    end
    return g
end
local function phaseStats(name)
    if C.stats[name]==nil then C.stats[name]={attempts=0,samples=0,gaps=0,caps=0,nodes=0,maxNodes=0,bytes=0,empty=0,
        stopZero=0,stopOne=0,newNodeFlag=0,drawProgramNodes=0,drawGatePass=0,drawAlphaZero=0,drawMeshDisabled=0,drawGateUnknown=0,
        addresses={},addressCount=0} end
    return C.stats[name]
end
local function rememberPrograms(g,phase,frame)
    if C.savedParentArray~=nil and not sameBytes(C.savedParentArray.bytes,g.arrayBytes) then return false,"parent callback array changed between graph samples" end
    if C.savedParentArray==nil then C.savedParentArray={address=g.arrayAddress,bytes=copyBytes(g.arrayBytes)} end
    for key,record in pairs(g.programs) do
        local old=C.programs[key]
        if old~=nil and (old.address~=record.address or not sameBytes(old.bytes,record.bytes)) then return false,"callback object changed between graph samples" end
        if old==nil then
            C.programs[key]=record
            if CONFIG.VERBOSE_RAW then
                emit(string.format("CHILD CALLBACK OBJECT phase=%s frame=%d encoded=%s bank=%d address=%s bytes=%d hex=%s bounded_window_not_struct_size=true not_called=true",
                    phase,frame,valueText(key),record.bank,pointerText(record.address),#record.bytes,exactBytesKey(record.bytes)),false)
            end
            for _,field in ipairs(record.fields) do
                C.targets[field.rva]=true
                emit(string.format("CHILD CALLBACK POINTER encoded=%s offset=%s rva=%s role=%s observed_pointer_not_instruction_hit=true",
                    valueText(key),valueText(field.offset),valueText(field.rva),field.role),true)
            end
        end
    end
    return true
end
function C.observe(phase,snapshot,sample)
