    local s=phaseStats(phase.name); s.attempts=s.attempts+1
    local graph,why=captureChildGraph(snapshot,sample)
    if graph==nil then
        s.gaps=s.gaps+1
        if tostring(why):find("CAP:",1,true) then s.caps=s.caps+1 end
        emit(string.format("CHILD GRAPH GAP phase=%s frame=%d reason=%s counted_as_child_absence=false no_global_negative_claim=true",phase.name,sample.frame,tostring(why)),s.gaps<=8)
        return true
    end
    C.lastGraph=graph
    local remembered,rememberWhy=rememberPrograms(graph,phase.name,sample.frame)
    if not remembered then return false,rememberWhy end
    s.samples=s.samples+1; s.nodes=s.nodes+#graph.nodes; s.maxNodes=math.max(s.maxNodes,#graph.nodes); s.bytes=s.bytes+graph.bytes
    if #graph.nodes==0 then s.empty=s.empty+1 end
    local stop=graph.parent[0x92]
    if stop==0 then s.stopZero=s.stopZero+1 elseif stop==1 then s.stopOne=s.stopOne+1 end
    emit(string.format("CHILD GRAPH SAMPLE phase=%s frame=%d tick=%d record=%s identity=%s state14=%s actor1CC=%s stop91=%d age58=%s age5C=%s flagsD5=%d flagsD8=%d groups=%d linked_children=%d parent_head78=%s row_base88=%s raw_graph_bytes=%d bracketing=all_saved_spans_and_canonical_focus not_atomic=true",
        phase.name,sample.frame,sample.tick,pointerText(snapshot.recordPointer),valueText(snapshot.layout.identity),valueText(snapshot.layout.state14),valueText(snapshot.actorEventFlags),stop,
        valueText(decodeU32(graph.parent,0x59)),valueText(decodeU32(graph.parent,0x5D)),graph.parent[0xD6],graph.parent[0xD9],#graph.rows,#graph.nodes,valueText(graph.headKey),pointerText(graph.rowBase),graph.bytes),false)
    if CONFIG.VERBOSE_RAW then
        emit(string.format("CHILD PARENT RAW phase=%s frame=%d address=%s bytes=224 hex=%s",phase.name,sample.frame,pointerText(snapshot.blockBase),exactBytesKey(graph.parent)),false)
    end
    if CONFIG.VERBOSE_RAW then
        emit(string.format("CHILD RUNTIME ROWS RAW phase=%s frame=%d address=%s bytes=%d hex=%s",phase.name,sample.frame,pointerText(graph.rowBase),#graph.rowBytes,exactBytesKey(graph.rowBytes)),false)
    end
    for address,d in pairs(graph.definitions) do
        if CONFIG.VERBOSE_RAW then
            emit(string.format("CHILD DEFINITION RAW phase=%s frame=%d address=%s properties=%d payload_offset=%s allocation_bytes=%d bytes=%d hex=%s",phase.name,sample.frame,pointerText(address),d.count,valueText(d.payload),d.childBytes,#d.bytes,exactBytesKey(d.bytes)),false)
        end
    end
    for _,node in ipairs(graph.nodes) do
        if not s.addresses[node.address] then s.addresses[node.address]=true; s.addressCount=s.addressCount+1 end
        local bytes=node.bytes
        if bytes[0x9F]~=0 then s.newNodeFlag=s.newNodeFlag+1 end
