local function worldMatrix(bytes)
    if bytes==nil or #bytes~=STRIDE then return nil,"native world matrix unreadable/changed" end
    local matrix={}
    for i=1,16 do
        local value=H.decodeFloat(decodeU32(bytes,(i-1)*4+1))
        if value==nil or math.abs(value)>CONFIG.VECTOR_ABS_BOUND then return nil,"nonfinite/out-of-bound native matrix component" end
        matrix[i]=value
    end
    if math.abs(matrix[4])>0.00001 or math.abs(matrix[8])>0.00001 or math.abs(matrix[12])>0.00001 or matrix[16]~=1 then
        return nil,"native pose matrix is not affine with W1"
    end
    local maxNormError,maxDot=0,0
    for row=0,2 do
        local norm=0;for c=1,3 do norm=norm+matrix[row*4+c]^2 end
        maxNormError=math.max(maxNormError,math.abs(norm-1))
    end
    for _,rows in ipairs({{0,1},{0,2},{1,2}}) do
        local dot=0;for c=1,3 do dot=dot+matrix[rows[1]*4+c]*matrix[rows[2]*4+c] end
        maxDot=math.max(maxDot,math.abs(dot))
    end
    if maxNormError>0.03 or maxDot>0.03 then return nil,"native world matrix basis is not near orthonormal" end
    return matrix,nil,{normError=maxNormError,dotError=maxDot}
end
local function sampleMatrix(route)
    local current,why=P.current(route);if not current then return nil,why end
