    local anchor=point(bytes,0x30)
    local separation=distance(anchor,actor)
    local actorAfter=doubleRead(identity.route.sora+0x10,16)
    if not sameBytes(actorBytes,actorAfter) then return nil,"actor world position changed around native matrix read" end
    local after,afterWhy=P.current(route);if not after then return nil,afterWhy end
    if actor==nil then return nil,"actor world position unreadable/nonfinite/out-of-bound" end
    if separation>300 then
        return nil,"native joint205 WORLD anchor fails the unchanged 300-unit Sora proximity bound",
            {classification="PROXIMITY_ONLY",bytes=bytes,actorBytes=actorBytes,separation=separation}
    end
    return {bytes=bytes,matrix=matrix,joint=identity.matrixAddress,address=identity.matrixAddress,
        actorBytes=actorBytes,separation=separation,basis=basis}
end
local function endpoints(window)
