            return false,why,false
        end
        P.identity=identity;P.physicalSlot=identity.slot
        for _,span in ipairs(identity.spans) do
            emit(string.format("NATIVE LEFT HAND BINDING FIELD role=%s address=%s bytes=%d hex=%s identity_only_no_writes=true",
                span.role,pointerText(span.address),#span.bytes,exactBytesKey(span.bytes)),false)
        end
