        S.imageCalls,S.slotCalls,boolText(S.linkAttempted),S.status,S.nativeAttempts,pointerText(S.result),S.overlaps,S.independentBuffers,pointerText(S.original),valueText(S.creatorKey),boolText(S.observedSibling),boolText(S.siblingGone),boolText(S.originalGone),S.pendingGraphWindows,pointerText(slot),boolText(slot==0),S.cleanupOutcome,boolText(S.unverified),boolText(S.imageCalls>0)),true)
