function T.resetEvent()
    if G.hasOwnership() or S.unverified or G.unverified then return false,"cannot reset owned/unverified event" end
    if T.eventIndex>0 and S.imageCalls>0 then
        local ready,why=S.reuseGate();if not ready then return false,"event reset lacks retired/NULL private image: "..tostring(why) end
    elseif T.eventIndex>0 and (S.attempted or S.linkAttempted or S.pending or S.slot()~=0)then
        return false,"event reset after an unpublished skip has staged/published work"
    end
    for k,v in pairs(S) do if type(v)~="function" and not keepS[k] then S[k]=nil end end
    for k,v in pairs(defaultsS) do S[k]=clone(v) end
    for k,v in pairs(G) do if type(v)~="function" then G[k]=nil end end
    for k,v in pairs(defaultsG) do G[k]=clone(v) end
    C.stats={};C.lastGraph=nil;C.savedParentArray=nil
    R.nativeBlockProvenance=nil;R.observationBlockProvenance=nil
    R.first=nil;R.current=nil;R.eventEntries=0
    return true
end
