        #T.trials,#T.plan,#T.events,CONFIG.MAX_NATIVE_EVENTS,T.eventIndex,S.imageCalls,S.dataCalls,CONFIG.MAX_NATIVE_EVENTS-1,T.slotCalls,2*CONFIG.MAX_NATIVE_EVENTS,T.totalHistoryWords+(T.active and G.historyWords or 0),CONFIG.MAX_NATIVE_EVENTS*CONFIG.MAX_HISTORY_WRITES,T.totalCacheWords+(T.active and G.cacheWords or 0),CONFIG.MAX_NATIVE_EVENTS*CONFIG.MAX_CACHE_WRITES,T.totalHistoryAPIs+(T.active and G.historyCalls or 0),T.totalCacheAPIs+(T.active and G.cacheCalls or 0),boolText(G.hasOwnership()),boolText(T.active)),true)
