finish=function(status,reason)
    if R.stopped then return end
    R.forceReportSync=true
    local released=G.cleanup("terminal: "..tostring(reason))
    local detached=S.cleanup("terminal: "..tostring(reason))
    if not released or not detached or S.unverified or G.unverified then
        status="ABORTED";reason="callback/geometry cleanup or API readback requires restart; "..tostring(reason) end
    if status=="COMPLETE" and (#T.trials~=#T.plan or T.active or G.hasOwnership() or S.slot()~=0) then
        status="ABORTED";reason="requested trial coverage/retirement incomplete; "..tostring(reason) end
    if T.continuous and T.writeEvidence then
        R.forceReportSync=false;T.writeEvidence();R.forceReportSync=true
    end
    auditCurrent();T.audit()
    if T.continuous then T.motionAudit() end
    local terminal=(T.mixed and "NATIVE MIXED GAMEPLAY TEST " or T.lockAir and "NATIVE LOCK-ON AIR COMBO TEST " or "NATIVE MOVEMENT TURNING TEST ")..status.." reason="..tostring(reason)
    if not emit(terminal,false) then status="ABORTED";terminal=(T.mixed and "NATIVE MIXED GAMEPLAY TEST " or T.lockAir and "NATIVE LOCK-ON AIR COMBO TEST " or "NATIVE MOVEMENT TURNING TEST ").."ABORTED reason=report output failed" end
    console(terminal);R.status=status;R.reason=reason
    emit("Trail controller stopped. Return the integrated log after a reproducible failure;fully restart KH1FM. Do not press F1.",true)
    if not R.reportAvailable then R.status="ABORTED" end
    R.enabled=false;R.stopped=true
end
local function initializePhase()
