    return p
end
local function isGroundAttack(animation)
    return animation==0xC8 or animation==0xC9 or animation==0xCB
end
local function startEvent(snapshot)
    if T.eventIndex>=CONFIG.MAX_NATIVE_EVENTS then return false,"bounded native event cap reached; no further callback is published" end
    if T.eventIndex>0 then
