    end
    if T.lockAir then
        local entry,why=E.entry(snapshot);if not entry then return false,why end
        T.entryContext=entry
    elseif T.continuous and (T.draining or not isGroundAttack(snapshot.animation)) then return false,"new event outside the open tested ground-attack window" end
    T.eventIndex=T.eventIndex+1;T.trialEvents=T.trialEvents+1;T.active=true
    R.first=initializePhase();R.first.entryTick=R.tick;R.current=R.first;R.eventEntries=1
    emit(string.format("NATIVE EVENT BEGIN trial=%d mode=%s event=%d animation=%s tick=%d record=%s identity=%s a_reused_address_alone_is_not_a_new_epoch=true",T.trialIndex,tostring(mode()),T.eventIndex,valueText(snapshot.animation),R.tick,pointerText(snapshot.recordPointer),snapshot.layout and valueText(snapshot.layout.identity) or "PENDING"),true)
    return true
end
