function T.sampleMotion(snapshot,force)
    if T.lockAir and not T.mixed then return true end
    if not T.continuous or snapshot.recordPointer~=0
        or (T.mixed and E.kind(snapshot)~=nil)
        or (not T.mixed and isGroundAttack(snapshot.animation)) then return true end
    if not force and R.tick-(T.motion.lastTick or -1000)<CONFIG.MOTION_SAMPLE_INTERVAL then return true end
    local m=T.motion;m.lastTick=R.tick
    local actor=snapshot.route.sora
    if safeReadLong(SORA_POINTER_RVA,false)~=actor then m.gaps=m.gaps+1;return true end
    local position=safeReadArray(actor+0x10,16,true)
    local axes=safeReadArray(actor+0xD0,48,true)
    local positionAfter=safeReadArray(actor+0x10,16,true)
    local axesAfter=safeReadArray(actor+0xD0,48,true)
    if not sameBytes(position,positionAfter) or not sameBytes(axes,axesAfter)
        or safeReadLong(SORA_POINTER_RVA,false)~=actor then m.gaps=m.gaps+1;return true end
    local xyz,basis={},{}
    for i=1,3 do
        xyz[i]=H.decodeFloat(decodeU32(position,(i-1)*4+1))
        if xyz[i]==nil or math.abs(xyz[i])>CONFIG.VECTOR_ABS_BOUND then m.gaps=m.gaps+1;return true end
    end
    for row=0,2 do for column=0,2 do
        local value=H.decodeFloat(decodeU32(axes,row*16+column*4+1))
        if value==nil or math.abs(value)>CONFIG.VECTOR_ABS_BOUND then m.gaps=m.gaps+1;return true end
        basis[#basis+1]=value
    end end
    m.valid=m.valid+1
    if m.origin==nil then m.origin=xyz;m.originBasis=basis end
    local dx,dz=xyz[1]-m.origin[1],xyz[3]-m.origin[3]
    m.maxTravel=math.max(m.maxTravel,math.sqrt(dx*dx+dz*dz))
    local delta,step=0,0
    for i=1,9 do
        delta=math.max(delta,math.abs(basis[i]-m.originBasis[i]))
        if m.lastBasis then step=math.max(step,math.abs(basis[i]-m.lastBasis[i])) end
    end
    m.maxBasisDelta=math.max(m.maxBasisDelta,delta)
    if step>=0.1 then m.basisChanges=m.basisChanges+1 end
    m.lastBasis=basis
    if #m.samples<128 or step>=0.1 then
        local sample={tick=R.tick,animation=snapshot.animation,position=position,axes=axes}
        if #m.samples<128 then m.samples[#m.samples+1]=sample else m.samples[128]=sample end
    end
    return true
end
