        T.trialIndex,tostring(mode()),T.eventIndex,pointerText(p.recordAddress),valueText(p.identity),valueText(S.entryAnimation),G.applied,G.coverage,S.overlaps,S.independentBuffers,G.historyWords,G.cacheWords,p.liveOverlapSamples,boolText(mode()~="COMBO")),true)
