            emit(string.format("MOVEMENT ACTOR OBSERVATION tick=%d animation=%s position16_hex=%s actor_D0_E0_F0_48_hex=%s read_only=true sampled_outside_active_trail=true actor_basis_not_input_trace=true",s.tick,valueText(s.animation),exactBytesKey(s.position),exactBytesKey(s.axes)),false)
