    if T.trialFrames>=CONFIG.LIVE_CALLBACKS then T.requestDrain("the3600-callback observation window ended") end
    if T.eventIndex>=CONFIG.MAX_NATIVE_EVENTS then T.requestDrain("the60 native-event limit was reached") end
    if not T.active and snapshot.recordPointer~=0 and not T.draining then
