    T.trialFrames=T.trialFrames+1;E.phaseFrames=E.phaseFrames+1
    trackAnimation(snapshot);observeAudio(audio)
    local phase=E.phase=="GROUND" and E.ground or E.air
    if T.trialFrames>=CONFIG.LIVE_CALLBACKS and not E.ending then
        E.ending=true;E.endReason="combined3600-callback observation cap" end
    if not E.ending and (phase.starts>=30 or E.phaseFrames>=1800) then
        E.ending=true
        E.endReason="phase event/time bound reached"
    end
    if E.ending and not E.finishNotice then
        E.finishNotice=true;T.quiet=0
        T.notice("LOCK AIR "..E.phase.." FINISH: "..E.endReason..". Finish the current action,release Attack/movement,and stand still on the ground. Wait for AIR COMBO READY or COMPLETE/ABORTED. No new event starts during this pause.")
    end
    if not T.active and snapshot.recordPointer~=0 and not E.ending then
        local begun,why=startEvent(snapshot);if not begun then return false,why end
    end
    if T.active then
        local sample=makeSample(snapshot,queue,audio)
        local ok,why=nativeStep(snapshot,queue,audio,sample);if not ok then return false,why end
    end
    E.track(snapshot)
    -- Admit the third combo's final native epoch before requesting the pause.
    if not E.ending and phase.combos>=3 then
        E.ending=true;E.endReason="three combo sequences observed"
    end
    if E.ending then
        if E.quiet(snapshot,audio) then T.quiet=T.quiet+1 else T.quiet=0 end
        if T.quiet>=CONFIG.IDLE_BASELINE_SAMPLES then
            if not E.phaseCovered() then return false,"phase coverage incomplete at its bound;need three canonical three-hit sequences and at least three clean native epochs" end
            local ready,why=readyCheck(snapshot);if not ready then return false,why end
            if E.phase=="GROUND" then
                if T.trialFrames>=CONFIG.LIVE_CALLBACKS then return false,"combined callback budget exhausted before aerial phase" end
                E.audit();E.phase="AIR";E.phaseFrames=0;E.ending=false;E.finishNotice=false;E.finishFrame=nil;E.quietPosition=nil;T.quiet=0
                T.notice("AIR COMBO READY. Keep lock-on,then jump and perform THREE full basic aerial combos,landing between combos. Do not use ground attacks in this phase. At AIR FINISH,land,release Attack/movement and stand still until COMPLETE/ABORTED.")
