        T.notice(string.format("LOCK AIR PROGRESS phase=%s callbacks=%d/1800 native_events=%d/30 three_hit_sequences=%d/3. Follow the current phase until FINISH.",E.phase,E.phaseFrames,phase.closed,phase.combos))
    end
    R.lastAnimation=snapshot.animation
    return true
end

function T.handleContinuous(snapshot,queue,audio)
    if T.lockAir then return E.handle(snapshot,queue,audio) end
    T.trialFrames=T.trialFrames+1
    trackAnimation(snapshot);observeAudio(audio)
    if T.trialFrames>=CONFIG.LIVE_CALLBACKS then T.requestDrain("the one-minute observation window ended") end
    if T.eventIndex>=CONFIG.MAX_NATIVE_EVENTS then T.requestDrain("the session event limit was reached") end
