    end
    if T.active then
        local sample=makeSample(snapshot,queue,audio)
        local ok,why=nativeStep(snapshot,queue,audio,sample);if not ok then return false,why end
    end
    if not T.active then T.sampleMotion(snapshot,false) end
    if T.draining then
        if not T.active and snapshot.animation==R.idleAnimation and snapshot.recordPointer==0
            and #(audio.exact or {})==0 and not S.pending then T.quiet=T.quiet+1 else T.quiet=0 end
        if T.quiet>=CONFIG.IDLE_BASELINE_SAMPLES then
            if not T.coverageReady() then
