        elseif R.tick-T.drainTick>=CONFIG.DRAIN_CALLBACK_MAX then
            return false,"timed out waiting for the active event to retire and60 quiet idle callbacks"
        end
    elseif T.trialFrames%600==0 then
        T.notice(string.format("MOVEMENT TEST PROGRESS elapsed_callbacks=%d/3600 completed_events=%d/60 three_hit_combos=%d movement=%.1f basis_changes=%d. Keep mixing ground singles/combos with walking and turns until FINISH.",T.trialFrames,#T.events,T.completedCombos,T.motion.maxTravel,T.motion.basisChanges))
