local function resetBaseline(reason)
    if R.idleSamples>0 then emit("IDLE BASELINE RESET reason="..tostring(reason),true) end
    R.stage="wait_route";R.routeKey=nil;R.idleAnimation=nil;R.lastAnimation=nil
    R.idleSamples=0;R.baseline={};R.preRing={};R.armedTrailingGaps=0
end
local function handleCoherent(snapshot,queue,audio)
    R.incoherentConsecutive=0;R.lastSnapshot=snapshot;observeBankScope(snapshot)
    if T.lockAir and (R.stage=="wait_route" or R.stage=="idle_baseline") and not E.targetPresent(snapshot) then
        if R.stage=="idle_baseline" then resetBaseline("target reference absent during setup") end
        if R.tick%120==0 then T.notice("MIXED SETUP WAIT. Equip Kingdom Key,choose a durable lockable target in this room,lock on and stand still. No Attack until MIXED GAMEPLAY READY. Target memory is not read.") end
        return
