        if snapshot.animation==CONFIG.TARGET_ANIMATION or snapshot.recordPointer~=0 or #(audio.exact or {})~=0 then return end
        local fresh,why=validateFreshNativeAsset(snapshot);if not fresh then finish("ABORTED","fresh native asset gate: "..tostring(why));return end
        local blank,blankWhy=S.blankGate();if not blank then finish("ABORTED",blankWhy);return end
