        if not prepared then if terminal then finish("ABORTED","left-hand preparation: "..tostring(poseWhy)) end;return end
        R.routeKey=coreRouteKey(snapshot.route);R.idleAnimation=snapshot.animation;R.lastAnimation=snapshot.animation;R.stage="idle_baseline"
        emit("EXACT KINGDOM KEY ROUTE PASS: "..routeText(snapshot.route),true)
