        local pair,why=P.capture(snapshot.route);if pair==nil then finish("ABORTED","idle native pose: "..tostring(why));return end
        local sample=makeSample(snapshot,queue,audio);R.idleSamples=R.idleSamples+1;R.baseline[#R.baseline+1]=sample;ringPush(sample)
