            finish("ABORTED","another C8 began during an isolated trial; wait for its next READY prompt");return end
        if not T.active and snapshot.recordPointer~=0 then
            if mode()~="COMBO" then finish("ABORTED","unexpected additional native epoch during isolated trial");return end
            local begun,why=startEvent(snapshot);if not begun then finish("ABORTED",why);return end
        end
        local sample=makeSample(snapshot,queue,audio)
        if T.active then local ok,why=nativeStep(snapshot,queue,audio,sample);if not ok then finish("ABORTED",why);return end end
        -- Matching queue slots can retain old records; they are observations,
        -- not evidence that the canonical registration remains active.
