        else T.quiet=0 end
        if T.trialFrames>=CONFIG.OBSERVATION_CALLBACKS and T.quiet>=CONFIG.IDLE_BASELINE_SAMPLES then
            local ok,why=completeTrial(snapshot);if not ok then finish("ABORTED",why);return end
        elseif T.trialFrames%60==0 then
            emit(string.format("TRIAL PROGRESS trial=%d mode=%s callback=%d/%d events=%d active=%s quiet_idle=%d/60",T.trialIndex,tostring(mode()),T.trialFrames,CONFIG.TRIAL_CALLBACK_MAX,T.trialEvents,boolText(T.active),T.quiet),true)
        end
    end
