    elseif R.stage=="idle_baseline" then resetBaseline("baseline acquisition gap: "..tostring(reason))
    else
        if R.current then R.current.gaps=R.current.gaps+1 end
        finish("ABORTED","post-baseline acquisition gap: "..tostring(reason))
    end
end
