local function unsigned32(value)
    local number = tonumber(value) or 0
    if number < 0 then number = number + 4294967296 end
    return number % 4294967296
end

local function safeReadByte(address, absolute)
    local ok, value = pcall(ReadByte, address, absolute == true)
    if not ok or value == nil then return nil end
    return value
end

local function safeReadInt(address, absolute)
    local ok, value = pcall(ReadInt, address, absolute == true)
    if not ok or value == nil then return nil end
    return unsigned32(value)
end

local function safeReadLong(address, absolute)
    local ok, value = pcall(ReadLong, address, absolute == true)
    if not ok or value == nil then return nil end
    return value
end

local function safeReadFloat(address, absolute)
    local ok, value = pcall(ReadFloat, address, absolute == true)
    if not ok or value == nil or value ~= value
        or value == math.huge or value == -math.huge then
        return nil
    end
    return value
end

local function safeReadArray(address, count, absolute)
    local ok, value = pcall(ReadArray, address, count, absolute == true)
    if not ok or value == nil or #value ~= count then return nil end
    return value
end

local function safeWriteByte(address, value, absolute)
    local expected = unsigned32(value) % 0x100
    local ok = pcall(WriteByte, address, expected, absolute == true)
    if not ok then return false end
    return safeReadByte(address, absolute) == expected
end

local function safeWriteLong(address, value, absolute)
    local expected = tonumber(value) or 0
    local ok = pcall(WriteLong, address, expected, absolute == true)
    if not ok then return false end
    return safeReadLong(address, absolute) == expected
end

local function safeWriteArray(address, bytes, absolute)
    local ok = pcall(WriteArray, address, bytes, absolute == true)
    if not ok then return false end
    local readback = safeReadArray(address, #bytes, absolute)
    if readback == nil then return false end
    for index = 1, #bytes do
        if readback[index] ~= bytes[index] then return false end
    end
    return true
end

local function sameBytes(left, right)
    if left == nil or right == nil or #left ~= #right then return false end
    for index = 1, #left do
        if left[index] ~= right[index] then return false end
    end
    return true
end

local function allZero(bytes)
    if bytes == nil then return false end
    for index = 1, #bytes do
        if bytes[index] ~= 0 then return false end
    end
    return true
end

local function ownCave(bytes)
    if bytes == nil or #bytes ~= #CAPTURE_CAVE_IMAGE then return false end
    for index = 1, CAPTURE_CODE_SIZE do
        if bytes[index] ~= CAPTURE_CAVE_IMAGE[index] then return false end
    end
    local markerOffset = CAPTURE_MARKER_RVA - CAPTURE_CAVE_RVA
    for index = 1, #CAPTURE_MARKER do
        if bytes[markerOffset + index] ~= CAPTURE_MARKER[index] then return false end
    end
    local gate = bytes[CAPTURE_GATE_RVA - CAPTURE_CAVE_RVA + 1]
    local guard = bytes[RECURSION_GUARD_RVA - CAPTURE_CAVE_RVA + 1]
    return (gate == 0 or gate == 1 or gate == 2) and guard == 0
end

local function privateThemeLeaseState()
    local builder=safeReadArray(BUILDER_CALL_RVA,5,false)
    local cave=safeReadArray(CAPTURE_CAVE_RVA,CAPTURE_CAVE_SIZE,false)
    if sameBytes(builder,BUILDER_CALL_CUSTOM)and ownCave(cave)then return false end
    return nil
end

local function relativeCallBytes(site, target)
    local displacement = unsigned32(target - (site + 5))
    return {
        0xE8,
        displacement % 0x100,
        math.floor(displacement / 0x100) % 0x100,
        math.floor(displacement / 0x10000) % 0x100,
        math.floor(displacement / 0x1000000) % 0x100,
    }
end

local function pointerText(value)
    if value == nil or value == 0 then return "0x0" end
    local ok, result = pcall(string.format, "0x%X", math.floor(value))
    return ok and result or tostring(value)
end

local function scriptDirectory()
    if type(SCRIPT_PATH) == "string" and #SCRIPT_PATH > 0 then return SCRIPT_PATH end
    if debug == nil or debug.getinfo == nil then return nil end
    local ok, info = pcall(debug.getinfo, 1, "S")
    if not ok or info == nil or info.source == nil then return nil end
    local source = info.source
    if string.sub(source, 1, 1) == "@" then source = string.sub(source, 2) end
    return string.match(source, "^(.*)[\\/]")
end

local function console(message, messageType)
    local line = PREFIX .. tostring(message)
    local ok = pcall(ConsolePrint, line, messageType)
    if not ok then pcall(print, line) end
end

local function emit(message,level) return Shared.log("DAMAGE "..tostring(message),type(level)=="number"and level>=3)end

local function initializeReport() runtime.reportPath=Shared.reportPath;runtime.reportOpen=true end

local function emitCodeDump(name, rva, count)
    local bytes = safeReadArray(rva, count, false)
    if bytes == nil then
        emit(string.format("CODE DUMP FAILED name=%s rva=0x%X size=0x%X",
            tostring(name), rva, count), 3)
        return false
    end
    emit(string.format("CODE DUMP BEGIN name=%s rva=0x%X size=0x%X",
        tostring(name), rva, count), 1)
    for offset = 0, count - 1, 16 do
        local values = {}
        local last = math.min(count - 1, offset + 15)
        for current = offset, last do
            values[#values + 1] = string.format("%02X", bytes[current + 1])
        end
        emit(string.format("CODE %s +0x%03X: %s",
            tostring(name), offset, table.concat(values, " ")))
    end
    emit("CODE DUMP END name=" .. tostring(name), 1)
    return true
end

local function refuse(reason)
    runtime.stopped = true
    runtime.enabled = false
    emit("INSTALL REFUSED WITHOUT HOOK WRITE: " .. tostring(reason), 3)
    emit("Fully restart KH1FM before changing this executable-hook test.", 2)
end

local setHookFlag

local function formulaState()
    local bytes = safeReadArray(
        DAMAGE_FORMULA_CALL_RVA, #DAMAGE_FORMULA_CALL_NATIVE, false
    )
    if bytes == nil then return "unreadable" end
    if sameBytes(bytes, DAMAGE_FORMULA_CALL_NATIVE) then return "native" end
    if sameBytes(bytes, DAMAGE_FORMULA_CALL_EQUIPMENT_V46) then
        if safeReadInt(EQUIPMENT_V46_SENTINEL_RVA, false)
            == EQUIPMENT_V46_SENTINEL then
            return "equipment_v46"
        end
        return "equipment_v46_incomplete"
    end
    return "foreign"
end

local function installHook()
    local builderHook = safeReadArray(
        BUILDER_CALL_RVA, #BUILDER_CALL_NATIVE, false
    )
    local formulaHook = safeReadArray(
        DAMAGE_FORMULA_CALL_RVA, #DAMAGE_FORMULA_CALL_NATIVE, false
    )
    local custom = relativeCallBytes(BUILDER_CALL_RVA, CAPTURE_CAVE_RVA)
    local cave = safeReadArray(CAPTURE_CAVE_RVA, CAPTURE_CAVE_SIZE, false)
    local before = safeReadArray(
        CAPTURE_BOUNDARY_BEFORE_RVA, #CAPTURE_BOUNDARY_BEFORE, false
    )
    local after = safeReadArray(
        CAPTURE_BOUNDARY_AFTER_RVA, #CAPTURE_BOUNDARY_AFTER, false
    )
    if builderHook == nil or formulaHook == nil or cave == nil
        or before == nil or after == nil then
        return false, "builder/formula hook, integration cave, or cave boundary is unreadable"
    end
    if not sameBytes(before, CAPTURE_BOUNDARY_BEFORE)
        or not sameBytes(after, CAPTURE_BOUNDARY_AFTER) then
        return false, "executable-cave boundary mismatch at +0x3ADED8; no cave write was attempted"
    end
    local owner = formulaState()
    if owner ~= "native" and owner ~= "equipment_v46" then
        return false, "formula call is neither native nor the verified Equipment/LIMIT v4.6 owner (state="
            .. tostring(owner) .. ")"
    end

    if sameBytes(builderHook, custom) then
        if not ownCave(cave) then
            return false, "integration hook is present but its private cave changed"
        end
        if not safeWriteByte(CAPTURE_GATE_RVA, 0, false) then
            return false, "existing integration request gate could not be cleared"
        end
        if not safeWriteLong(EXPECTED_TARGET_RVA, 0, false) then
            return false, "existing expected-target field could not be cleared"
        end
        runtime.formulaOwner = owner == "equipment_v46"
            and "EQUIPMENT_LIMIT_V46_COEXISTENCE"
            or "NATIVE_FORMULA_AWAITING_EQUIPMENT_V46"
        runtime.equipmentSeen = owner == "equipment_v46"
        runtime.hookFlag = 0
        return true, "reused exact Equipment-integration hook"
    end
    if not sameBytes(builderHook, BUILDER_CALL_NATIVE) then
        return false, "native wrapper builder CALL is not original; remove every older hit test, then fully restart"
    end
    if not allZero(cave) and not ownCave(cave) then
        return false, "verified +0x3ADED8..+0x3ADFFF interval is not empty"
    end

    if not ownCave(cave) then
        if not safeWriteArray(CAPTURE_CAVE_RVA, CAPTURE_CAVE_IMAGE, false) then
            return false, "integration native-wrapper image write did not verify"
        end
    else
        if not safeWriteByte(CAPTURE_GATE_RVA, 0, false) then
            return false, "existing integration request gate could not be cleared"
        end
        if not safeWriteLong(EXPECTED_TARGET_RVA, 0, false) then
            return false, "existing expected-target field could not be cleared"
        end
    end

    -- The builder-call branch is installed only after the full image verifies.
    if not safeWriteArray(BUILDER_CALL_RVA, custom, false) then
        return false, "native wrapper builder-call branch write did not verify"
    end
    runtime.formulaOwner = owner == "equipment_v46"
        and "EQUIPMENT_LIMIT_V46_COEXISTENCE"
        or "NATIVE_FORMULA_AWAITING_EQUIPMENT_V46"
    runtime.equipmentSeen = owner == "equipment_v46"
    runtime.hookFlag = 0
    return true, "installed post-primary-builder Equipment-integration hook"
end

local function monitorFormulaOwner()
    local owner=formulaState()
    if owner=="native"or owner=="equipment_v46"then return true end
    setHookFlag(0);runtime.stopped=true;runtime.enabled=false
    emit("DAMAGE STOPPED: formula ownership changed to "..tostring(owner),true)
    return false
end

setHookFlag = function(desired)
    local value = tonumber(desired) or 0
    if value ~= 0 and value ~= 1 then value = 0 end
    local current = safeReadByte(CAPTURE_GATE_RVA, false)
    if current == nil or (current ~= 0 and current ~= 1 and current ~= 2) then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: offhand request gate became unreadable or invalid; no further writes.", 3)
        return false
    end
    if current == 2 then
        -- A completed builder result belongs to pollHookResult(). Do not let a
        -- same-frame motion transition erase it before qualification.
        if value ~= 0 then return false end
        runtime.hookFlag = 2
        return true
    end
    if current ~= value and not safeWriteByte(CAPTURE_GATE_RVA, value, false) then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: offhand request gate-byte write failed; no further writes.", 3)
        return false
    end
    runtime.hookFlag = value
    if value == 0 then
        runtime.pendingRequestKind = nil
        runtime.pendingRequestAnimation = 0
        runtime.pendingRequestSerial = 0
    end
    return true
end

local function setExpectedTarget(target)
    local value = tonumber(target) or 0
    local current = safeReadLong(EXPECTED_TARGET_RVA, false)
    if current == nil then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: expected-target field became unreadable; no further writes.", 3)
        return false
    end
    if current ~= value and not safeWriteLong(EXPECTED_TARGET_RVA, value, false) then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: expected-target field write failed; no further writes.", 3)
        return false
    end
    return true
end

local function emitDwordRegion(label, address, count)
    if address < 0x10000 or address > 0x00007FFFFFFFFFFF then
        emit(tostring(label) .. " REGION SKIPPED: invalid pointer "
            .. pointerText(address), 2)
        return
    end
    for offset = 0, count - 1, 0x20 do
        emit(string.format(
            "%s DWORDS +0x%02X: %08X %08X %08X %08X %08X %08X %08X %08X",
            tostring(label), offset,
            safeReadInt(address + offset + 0x00, true) or 0,
            safeReadInt(address + offset + 0x04, true) or 0,
            safeReadInt(address + offset + 0x08, true) or 0,
            safeReadInt(address + offset + 0x0C, true) or 0,
            safeReadInt(address + offset + 0x10, true) or 0,
            safeReadInt(address + offset + 0x14, true) or 0,
            safeReadInt(address + offset + 0x18, true) or 0,
            safeReadInt(address + offset + 0x1C, true) or 0
        ))
    end
end

local function validationKey(model, jointCount)
    return string.format(
