        runtime.airQualifiedByAnimation[0xCD] or 0,
        runtime.airQualifiedByAnimation[0xCE] or 0
    )
end

local function pollHookResult()
    local current = safeReadByte(CAPTURE_GATE_RVA, false)
    local guard = safeReadByte(RECURSION_GUARD_RVA, false)
    if current == nil or (current ~= 0 and current ~= 1 and current ~= 2)
        or guard == nil or guard ~= 0 then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: offhand request gate/guard state is invalid; no further writes.", 3)
        return false
    end
    if current == 2 then
        local sequence = safeReadInt(CAPTURE_SEQUENCE_RVA, false) or 0
        local attackContext = safeReadLong(
            CAPTURE_ATTACK_CONTEXT_RVA, false
        ) or 0
        local targetMaskBefore = safeReadInt(
            TARGET_MASK_BEFORE_RVA, false
        ) or 0
        local targetMaskAfter = safeReadInt(
            TARGET_MASK_AFTER_RVA, false
        ) or 0
        local primaryRecord = safeReadLong(
            CAPTURE_PRIMARY_RECORD_RVA, false
        ) or 0
        local secondaryRecord = safeReadLong(
            CAPTURE_SECONDARY_RECORD_RVA, false
        ) or 0
        local primaryValid = primaryRecord >= 0x10000
            and primaryRecord <= 0x00007FFFFFFFFFFF
        local secondaryValid = secondaryRecord >= 0x10000
            and secondaryRecord <= 0x00007FFFFFFFFFFF
        local primaryDamage = primaryValid
            and (safeReadInt(primaryRecord + 0x08, true) or 0) or 0
        local primarySequence = primaryValid
            and (safeReadInt(primaryRecord + 0x24, true) or 0) or 0
        local primarySelector = primaryValid
            and (safeReadInt(primaryRecord + 0x28, true) or 0) or 0
        local secondaryDamage = secondaryValid
            and (safeReadInt(secondaryRecord + 0x08, true) or 0) or 0
        local secondarySequence = secondaryValid
            and (safeReadInt(secondaryRecord + 0x24, true) or 0) or 0
        local secondarySelector = secondaryValid
            and (safeReadInt(secondaryRecord + 0x28, true) or 0) or 0
        local resultStatus = secondaryRecord ~= 0 and 1 or 0
        local contextSelector = attackContext >= 0x10000
            and safeReadInt(
                attackContext + ATTACK_CONTEXT_SELECTOR_OFFSET, true
            ) or -1
        local offhandBitBefore = targetMaskBefore % (OFFHAND_SELECTOR * 2)
            >= OFFHAND_SELECTOR
        local offhandBitAfter = targetMaskAfter % (OFFHAND_SELECTOR * 2)
            >= OFFHAND_SELECTOR
        local primarySelectorExpected = primarySelector == PRIMARY_SELECTOR_1
            or primarySelector == PRIMARY_SELECTOR_2
        local submitted = resultStatus == 1 and secondaryRecord ~= 0
        local damageMatched = primaryDamage > 0
            and secondaryDamage > 0
            and secondaryDamage == primaryDamage
        local qualified = submitted
            and primarySelectorExpected
            and primaryRecord ~= 0
            and secondaryRecord ~= primaryRecord
            and damageMatched
            and secondarySequence > primarySequence
            and secondarySelector == OFFHAND_SELECTOR
            and not offhandBitBefore
            and offhandBitAfter
            and contextSelector == primarySelector
        local duplicateSuppressed = not submitted
            and primarySelectorExpected
            and primaryRecord ~= 0
            and offhandBitBefore
            and offhandBitAfter
            and contextSelector == primarySelector
        local motion = runtime.motion
        local resultKind = motion ~= nil
            and motion.kind or runtime.pendingRequestKind
        local resultAnimation = motion ~= nil
            and motion.animation or runtime.pendingRequestAnimation
        local resultSerial = motion ~= nil
            and motion.serial or runtime.pendingRequestSerial
        local probationAction = nil
        local probationState = nil
        if runtime.targetRequiresProbation then
            probationState = runtime.targetModelKey ~= nil
                and runtime.modelValidation[runtime.targetModelKey] or nil
            if probationState == nil or probationState.status ~= "probation" then
                probationAction = "quarantined"
                qualified = false
            elseif duplicateSuppressed then
                probationState.duplicateSkips =
                    probationState.duplicateSkips + 1
                probationAction = "duplicate-skipped"
            elseif not submitted then
                probationState.nativeRefusals =
                    probationState.nativeRefusals + 1
                probationAction = "native-refused"
            else
                probationState.submissions = probationState.submissions + 1
                if qualified then
                    probationState.qualified = probationState.qualified + 1
                    if probationState.qualified
                        >= CONFIG.UNKNOWN_REQUIRED_QUALIFIED then
                        probationState.status = "trusted"
                        runtime.targetRequiresProbation = false
                        runtime.targetClass = string.format(
                            "session-trusted-%d", runtime.targetJointCount
                        )
                        probationAction = "promoted"
                    else
                        probationAction = "qualified"
                    end
                else
                    probationState.status = "blocked"
                    probationAction = "quarantined"
                end
            end
        end
        local airAction = nil
        if resultKind == "air"
            and resultAnimation >= CONFIG.AIR_ANIMATION_MIN
            and resultAnimation <= CONFIG.AIR_ANIMATION_MAX then
            if duplicateSuppressed then
                runtime.airValidationDuplicateSkips =
                    runtime.airValidationDuplicateSkips + 1
            elseif not submitted then
                runtime.airValidationNativeRefusals =
                    runtime.airValidationNativeRefusals + 1
            else
                runtime.airValidationSubmissions =
                    runtime.airValidationSubmissions + 1
                if qualified then
                    runtime.airValidationQualified =
                        runtime.airValidationQualified + 1
                    runtime.airQualifiedByAnimation[resultAnimation] =
                        (runtime.airQualifiedByAnimation[resultAnimation] or 0)
                            + 1
                else
                    runtime.airValidationStatus = "blocked"
                    runtime.airBlockedReason = string.format(
                        "animation=0x%02X submitted=true qualified=false",
                        resultAnimation
                    )
                    airAction = "blocked"
                end
            end
        end
        runtime.totalAttempts = runtime.totalAttempts + 1
        -- Count the native result itself, even if Lua motion bookkeeping was
        -- lost during a same-frame reset. Result totals therefore describe
        -- submitted secondary records, not merely motions that survived long
        -- enough to receive their post-result annotation.
        if submitted then
            runtime.submittedOffhandEvents =
                runtime.submittedOffhandEvents + 1
        end
        if qualified then
            runtime.successfulOffhandEvents =
                runtime.successfulOffhandEvents + 1
            local joints = runtime.targetJointCount
            runtime.qualifiedByJointCount[joints] =
                (runtime.qualifiedByJointCount[joints] or 0) + 1
            if not runtime.normalClassPassReported
                and (runtime.qualifiedByJointCount[126] or 0) > 0
                and (runtime.qualifiedByJointCount[130] or 0) > 0 then
                runtime.normalClassPassReported = true
                emit(string.format(
                    "V89 NORMAL-CLASS COEXISTENCE PASS: joints126=%d joints130=%d. Continuous integration remains active.",
                    runtime.qualifiedByJointCount[126],
                    runtime.qualifiedByJointCount[130]
                ), 1)
            end
        elseif submitted then
            runtime.rejectedOffhandEvents =
                runtime.rejectedOffhandEvents + 1
        end
        if motion ~= nil then
            motion.contextCaptured = true
            motion.captureFrame = motion.lastFrame
            motion.nativeDamage = primaryDamage
            motion.primarySequence = primarySequence
            motion.primarySelector = primarySelector
            motion.secondarySubmitted = submitted
            motion.secondaryQualified = qualified
            motion.secondaryRecord = secondaryRecord
            motion.secondaryDamage = secondaryDamage
            motion.secondarySequence = secondarySequence
            motion.secondarySelector = secondarySelector
            motion.targetMaskBefore = targetMaskBefore
            motion.targetMaskAfter = targetMaskAfter
            motion.contextRestored = contextSelector == primarySelector
            emit(string.format(
                "BUILDER-COUPLED ATTEMPT serial=%d kind=%s animation=0x%02X attempt_sequence=%d builder_frame=%.3f request_armed=%s contact_confirmed=%s arm_mode=%s result_status=%d submitted=%s qualified=%s total_attempts=%d",
                motion.serial, motion.kind, motion.animation, sequence,
                motion.captureFrame or -1.0, tostring(motion.contactArmed),
                tostring(motion.contactConfirmed),
                tostring(motion.armMode or "none"),
                resultStatus, tostring(submitted), tostring(qualified),
                runtime.totalAttempts
            ), qualified and 1 or (duplicateSuppressed and 2 or 3))
            emit(string.format(
                "DISTINCT SELECTOR INPUT attack_context=%s locked_target=%s primary_selector=%d offhand_selector=%d target_mask_before=0x%08X target_mask_after=0x%08X offhand_bit_before=%s offhand_bit_after=%s context_restored=%s",
                pointerText(attackContext), pointerText(runtime.target),
                primarySelector, OFFHAND_SELECTOR,
                targetMaskBefore, targetMaskAfter,
                tostring(offhandBitBefore), tostring(offhandBitAfter),
                tostring(contextSelector == primarySelector)
            ), duplicateSuppressed and 2 or (primarySelectorExpected
                and not offhandBitBefore and offhandBitAfter
                and contextSelector == primarySelector and 1 or 3))
            emit(string.format(
                "PRIMARY BUILDER EVENT record=%s damage=%d sequence=%d selector=%d",
                pointerText(primaryRecord), primaryDamage,
                primarySequence, primarySelector
            ))
            emit(string.format(
                "SECONDARY FULL-WRAPPER EVENT record=%s distinct_record=%s damage=%d damage_matches_primary=%s sequence=%d selector=%d selector_expected=%s sequence_advanced=%s",
                pointerText(secondaryRecord),
                tostring(secondaryRecord ~= 0
                    and secondaryRecord ~= primaryRecord),
                secondaryDamage, tostring(damageMatched),
                secondarySequence, secondarySelector,
                tostring(secondarySelector == OFFHAND_SELECTOR),
                tostring(secondarySequence > primarySequence)
            ), qualified and 1 or (duplicateSuppressed and 2 or 3))
            if secondaryRecord >= 0x10000
                and secondaryRecord <= 0x00007FFFFFFFFFFF then
                emitDwordRegion("SECONDARY FULL-WRAPPER RECORD", secondaryRecord, 0x40)
            end
        else
            emit(string.format(
                "WARNING: completed builder-coupled attempt had no active motion; preserved_request serial=%d kind=%s animation=0x%02X was still processed before the gate cleared.",
                resultSerial, tostring(resultKind), resultAnimation
            ), 2)
        end
        if not safeWriteByte(CAPTURE_GATE_RVA, 0, false) then
            runtime.stopped = true
            runtime.enabled = false
            emit("STOPPED: consumed offhand request gate could not be cleared; no further writes.", 3)
            return false
        end
        runtime.hookFlag = 0
        runtime.pendingRequestKind = nil
        runtime.pendingRequestAnimation = 0
        runtime.pendingRequestSerial = 0
        if airAction == "blocked" then
            emit(string.format(
                "V97 AIR SUBMITTED-UNQUALIFIED / AIR DISABLED: %s coverage={%s} qualified=%d submissions=%d. The frozen V95 ground route remains active; stop air use and send this report.",
                tostring(runtime.airBlockedReason), airCoverageText(),
                runtime.airValidationQualified,
                runtime.airValidationSubmissions
            ), 3)
        end
        if probationAction == "qualified" then
            emit(string.format(
                "UNKNOWN MODEL PROBATION QUALIFIED: model_key=%s qualified=%d/%d submissions=%d; model remains probationary.",
                tostring(runtime.targetModelKey), probationState.qualified,
                CONFIG.UNKNOWN_REQUIRED_QUALIFIED, probationState.submissions
            ), 1)
        elseif probationAction == "promoted" then
            emit(string.format(
                "UNKNOWN MODEL PROMOTED: model_key=%s joints=%d qualified=%d/%d submissions=%d duplicate_skips=%d native_refusals=%d; model is trusted for the rest of this Lua session.",
                tostring(runtime.targetModelKey), runtime.targetJointCount,
                probationState.qualified, CONFIG.UNKNOWN_REQUIRED_QUALIFIED,
                probationState.submissions, probationState.duplicateSkips,
                probationState.nativeRefusals
            ), 1)
        elseif probationAction == "duplicate-skipped" then
            emit(string.format(
                "UNKNOWN MODEL PROBATION DUPLICATE SKIP: model_key=%s target_mask_before=0x%08X already contained selector 4; no secondary record was submitted and probation remains %d/%d.",
                tostring(runtime.targetModelKey), targetMaskBefore,
                probationState.qualified, CONFIG.UNKNOWN_REQUIRED_QUALIFIED
            ), 1)
        elseif probationAction == "native-refused" then
            emit(string.format(
                "UNKNOWN MODEL PROBATION NATIVE REFUSAL: model_key=%s refusal_count=%d target_mask_before=0x%08X; no secondary record was submitted, so probation remains %d/%d without quarantine.",
                tostring(runtime.targetModelKey), probationState.nativeRefusals,
                targetMaskBefore, probationState.qualified,
                CONFIG.UNKNOWN_REQUIRED_QUALIFIED
            ), 2)
        elseif probationAction == "quarantined" then
            if probationState ~= nil then probationState.status = "blocked" end
            runtime.targetRouteReady = false
            runtime.targetRouteFailed = true
            runtime.targetRequiresProbation = false
            runtime.motion = nil
            if not setExpectedTarget(0) then return false end
            emit(string.format(
                "UNKNOWN MODEL SUBMITTED-UNQUALIFIED / QUARANTINED: model_key=%s joints=%d submitted=%s qualified=%s. Target unpublished; this model cannot write again until a full Lua/game restart.",
                tostring(runtime.targetModelKey), runtime.targetJointCount,
                tostring(submitted), tostring(qualified)
            ), 3)
        end
    else
        runtime.hookFlag = current
    end
    return true
end
local function readable(address, count)
    return type(address) == "number"
        and address >= 0x10000
        and address <= 0x00007FFFFFFFFFFF
        and safeReadArray(address, count or 0x10, true) ~= nil
end

local function resolveCompressedPointer(encoded)
    local value = unsigned32(encoded)
    if value < 0x80000000 then return 0 end
    local payload = value - 0x80000000
    local bank = math.floor(payload / POINTER_BANK_SIZE)
    if bank < 0 or bank >= POINTER_BANK_COUNT then return 0 end
    local bankBase = safeReadLong(POINTER_BANK_TABLE_RVA + bank * 8, false) or 0
    if bankBase == 0 then return 0 end
    local pointer = bankBase + (payload % POINTER_BANK_SIZE)
    return readable(pointer, 0x10) and pointer or 0
end

local function validCoordinate(value)
    return value ~= nil and math.abs(value) <= 1000000.0
end

local function vector(x, y, z)
    return { x = x, y = y, z = z }
end

local function add(left, right)
    return vector(left.x + right.x, left.y + right.y, left.z + right.z)
end

local function subtract(left, right)
    return vector(left.x - right.x, left.y - right.y, left.z - right.z)
end

local function multiply(value, scale)
    return vector(value.x * scale, value.y * scale, value.z * scale)
end

local function dot(left, right)
    return left.x * right.x + left.y * right.y + left.z * right.z
end

local function magnitude(value)
    return math.sqrt(math.max(0.0, dot(value, value)))
end

local function distance(left, right)
    if left == nil or right == nil then return math.huge end
    return magnitude(subtract(left, right))
end

local function actorPosition(actor)
    if actor == nil or actor == 0 then return nil end
    local x = safeReadFloat(actor + ACTOR_POSITION_OFFSET, true)
    local y = safeReadFloat(actor + ACTOR_POSITION_OFFSET + 4, true)
    local z = safeReadFloat(actor + ACTOR_POSITION_OFFSET + 8, true)
    if not validCoordinate(x) or not validCoordinate(y)
        or not validCoordinate(z) then
        return nil
    end
    return vector(x, y, z)
end

local function currentTarget()
    if runtime.sora == 0 then return 0 end
    local encoded = safeReadInt(runtime.sora + SORA_TARGET_REFERENCE_OFFSET, true) or 0
    local target = resolveCompressedPointer(encoded)
    if target == 0 or target == runtime.sora or actorPosition(target) == nil then
        return 0
    end
    return target
end

local function targetHpState(target)
    if target == nil or target == 0 then return nil end
    local encoded = safeReadInt(target + ACTOR_STAT_PAGE_REFERENCE_OFFSET, true) or 0
    local statPage = resolveCompressedPointer(encoded)
    if statPage == 0 then return nil end
    local currentHp = safeReadInt(statPage + STAT_CURRENT_HP_OFFSET, true)
    local maximumHp = safeReadInt(statPage + STAT_MAXIMUM_HP_OFFSET, true)
    if currentHp == nil or maximumHp == nil or maximumHp < 1
        or maximumHp > 0x7FFFFFFF or currentHp > maximumHp then
        return nil
    end
    return {
        statPage = statPage,
        currentHp = currentHp,
        maximumHp = maximumHp,
    }
end

local function isZeroWord(word)
    return word == POSITIVE_ZERO_BITS or word == NEGATIVE_ZERO_BITS
end

local function wordAt(bytes, position)
    local b0 = tonumber(bytes[position]) or 0
    local b1 = tonumber(bytes[position + 1]) or 0
    local b2 = tonumber(bytes[position + 2]) or 0
    local b3 = tonumber(bytes[position + 3]) or 0
    if b0 < 0 then b0 = b0 + 256 end
    if b1 < 0 then b1 = b1 + 256 end
    if b2 < 0 then b2 = b2 + 256 end
    if b3 < 0 then b3 = b3 + 256 end
    return b0 + b1 * 0x100 + b2 * 0x10000 + b3 * 0x1000000
end

local function floatFromWord(word)
    if word == nil then return nil end
    local sign = word >= 0x80000000 and -1.0 or 1.0
    local exponent = math.floor(word / 0x800000) % 0x100
    local mantissa = word % 0x800000
    if exponent == 0xFF then return nil end
    if exponent == 0 then
        if mantissa == 0 then return sign * 0.0 end
        return sign * (mantissa / 0x800000) * (2 ^ -126)
    end
    return sign * (1.0 + mantissa / 0x800000) * (2 ^ (exponent - 127))
end

local function smallFiniteFloatBits(word)
    local exponent = math.floor(word / 0x800000) % 0x100
    return exponent == 0 or (exponent >= 96 and exponent <= 130)
end

local ROTATION_WORD_OFFSETS = {
    0x00, 0x04, 0x08,
    0x10, 0x14, 0x18,
    0x20, 0x24, 0x28,
}

local function rowAffineAt(bytes, position)
    if wordAt(bytes, position + 0x3C) ~= FLOAT_ONE_BITS then return false end
    if not isZeroWord(wordAt(bytes, position + 0x0C))
        or not isZeroWord(wordAt(bytes, position + 0x1C))
        or not isZeroWord(wordAt(bytes, position + 0x2C)) then
        return false
    end
    for _, offset in ipairs(ROTATION_WORD_OFFSETS) do
        if not smallFiniteFloatBits(wordAt(bytes, position + offset)) then
            return false
        end
    end
    return true
end

local function affineTranslationFromBytes(bytes, position)
    if not rowAffineAt(bytes, position) then return nil end
    local x = floatFromWord(wordAt(bytes, position + 0x30))
    local y = floatFromWord(wordAt(bytes, position + 0x34))
    local z = floatFromWord(wordAt(bytes, position + 0x38))
    if not validCoordinate(x) or not validCoordinate(y)
        or not validCoordinate(z) then
        return nil
    end
    return vector(x, y, z)
end

local function matrixTranslation(address)
    local x = safeReadFloat(address + 0x30, true)
    local y = safeReadFloat(address + 0x34, true)
    local z = safeReadFloat(address + 0x38, true)
    if not validCoordinate(x) or not validCoordinate(y)
        or not validCoordinate(z) then
        return nil
    end
    return vector(x, y, z)
end

local function readJointMatrix(address)
    local values = {}
    local offsets = {
        0x00, 0x04, 0x08,
        0x10, 0x14, 0x18,
        0x20, 0x24, 0x28,
        0x30, 0x34, 0x38,
    }
    for index, offset in ipairs(offsets) do
        values[index] = safeReadFloat(address + offset, true)
        if values[index] == nil then return nil end
    end
    return values
end

local function transformPoint(point, matrix)
    return vector(
        point.x * matrix[1] + point.y * matrix[4]
            + point.z * matrix[7] + matrix[10],
        point.x * matrix[2] + point.y * matrix[5]
            + point.z * matrix[8] + matrix[11],
        point.x * matrix[3] + point.y * matrix[6]
            + point.z * matrix[9] + matrix[12]
    )
end

local function pointSegmentDistance(point, first, second)
    if point == nil or first == nil or second == nil then return math.huge end
    local segment = subtract(second, first)
    local denominator = dot(segment, segment)
    if denominator <= 0.000001 then return distance(point, first) end
    local amount = dot(subtract(point, first), segment) / denominator
    amount = math.max(0.0, math.min(1.0, amount))
    return distance(point, add(first, multiply(segment, amount)))
end

local function validMarker(marker)
    return marker == OFFHAND_VISIBLE_MARKER or marker == OFFHAND_HIDDEN_MARKER
end

local function validateCvbl(address)
    if address == 0 or not readable(address, 0x10) then return false end
    if safeReadInt(address + 0x00, true) ~= CVBL_MAGIC_OR_VERSION
        or safeReadInt(address + 0x04, true) ~= CVBL_DESCRIPTOR_COUNT
        or safeReadInt(address + 0x08, true) ~= CVBL_FLAGS then
        return false
    end
    local packet = address + OFFHAND_PACKET_OFFSET
    local marker = safeReadInt(packet + 0x00, true)
    if not (validMarker(marker)
        and safeReadInt(packet + 0x04, true) == OFFHAND_PACKET_SIZE
        and safeReadInt(packet + 0x08, true) == OFFHAND_VERTEX_COUNT
        and safeReadInt(packet + 0x0C, true) == 0
        and safeReadInt(packet + 0x10, true) == OFFHAND_RUNTIME_VERTEX_STRIDE
        and safeReadInt(packet + 0x14, true) == OFFHAND_VERTEX_COUNT
        and safeReadInt(packet + 0x1C, true) == 0
        and readable(packet + 0x20, OFFHAND_FILE_VERTEX_STRIDE)) then
        return false
    end
    local vertexReference = safeReadInt(packet + 0x18, true) or 0
    return resolveCompressedPointer(vertexReference) ~= 0
end

local function locateCvbl(model)
    local registryReference = safeReadInt(
        model + MODEL_RESOURCE_REGISTRY_REFERENCE_OFFSET, true
    ) or 0
    local registry = resolveCompressedPointer(registryReference)
    if registry == 0 then return false end
    local seen = {}
    for offset = 0, REGISTRY_POINTER_WINDOW - 8, 8 do
        local candidate = safeReadLong(registry + offset, true) or 0
        if candidate ~= 0 and not seen[candidate] then
            seen[candidate] = true
            if validateCvbl(candidate) then
                runtime.cvbl = candidate
                runtime.packet = candidate + OFFHAND_PACKET_OFFSET
                emit(string.format(
                    "V25 PACKET PASS registry=%s source_offset=0x%X cvbl=%s packet=%s",
                    pointerText(registry), offset, pointerText(candidate),
                    pointerText(runtime.packet)
                ), 1)
                return true
            end
        end
    end
    return false
end

local function targetModelFromMobj(mobj)
    if mobj == 0 or safeReadInt(mobj, true) ~= MOBJ_MAGIC then return 0, 0 end
    local modelReference = safeReadInt(mobj + 0x20, true) or 0
    local model = resolveCompressedPointer(modelReference)
    if model == 0 then return 0, 0 end
    local jointCount = safeReadInt(model, true) or 0
    if jointCount < 1 or jointCount > 2048 then return 0, 0 end
    return model, jointCount
end

local function poseSlotLimit(jointCount)
    local count = (tonumber(jointCount) or 0) + CONFIG.TARGET_POSE_EXTRA_SLOTS
    count = math.max(32, count)
    return math.min(CONFIG.TARGET_MAX_POSE_SLOTS, count)
end

local function probePoseBase(base, actorPos, jointCount)
    if base == nil or base == 0 or actorPos == nil then return nil end
    local slots = poseSlotLimit(jointCount)
    local bytes = safeReadArray(base, slots * CONFIG.MATRIX_STRIDE, true)
    if bytes == nil then return nil end
    local validCount = 0
    local nearCount = 0
    local currentRun = 0
    local maximumRun = 0
    local nearest = math.huge
    local signatureA = 0.0
    local signatureB = 0.0
    for slot = 0, slots - 1 do
        local position = slot * CONFIG.MATRIX_STRIDE + 1
        local translation = affineTranslationFromBytes(bytes, position)
        if translation ~= nil then
            validCount = validCount + 1
            currentRun = currentRun + 1
            maximumRun = math.max(maximumRun, currentRun)
            local delta = distance(translation, actorPos)
            nearest = math.min(nearest, delta)
            local weightA = slot % 5 + 1
            local weightB = slot % 7 + 1
            signatureA = signatureA
                + translation.x * weightA
                + translation.y * weightB
                + translation.z
            signatureB = signatureB
                + translation.x
                + translation.y * weightA
                + translation.z * weightB
            if delta <= CONFIG.MAX_TARGET_MATRIX_DISTANCE then
                nearCount = nearCount + 1
            end
        else
            currentRun = 0
        end
    end
    return {
        base = base,
        slots = slots,
        validCount = validCount,
        nearCount = nearCount,
        maximumRun = maximumRun,
        nearest = nearest,
        signatureA = signatureA,
        signatureB = signatureB,
    }
end

local function bankForPointer(pointer)
    if pointer == nil or pointer == 0 then return nil end
    for index = 0, POINTER_BANK_COUNT - 1 do
        local base = safeReadLong(POINTER_BANK_TABLE_RVA + index * 8, false) or 0
        if base ~= 0 and pointer >= base
            and pointer < base + POINTER_BANK_SIZE then
            return { index = index, base = base }
        end
    end
    return nil
end

local function prepareRecordedPoseCandidates()
    local bank = bankForPointer(runtime.soraRender)
    if bank == nil then
        emit("CANDIDATE PREPARE FAILED: Sora renderer is not in a pointer bank.", 3)
        runtime.targetRouteFailed = true
        return false
    end
    runtime.poseCandidates = {}
    runtime.poseCandidateSeen = {}
    runtime.poseCandidateIndex = 1
    runtime.bestPoseCandidate = nil
    local function addCandidate(base, source)
        local key = pointerText(base)
        if runtime.poseCandidateSeen[key] then return end
        runtime.poseCandidateSeen[key] = true
        runtime.poseCandidates[#runtime.poseCandidates + 1] = {
            base = base,
            source = source,
        }
        emit(string.format(
            "EXACT POSE CANDIDATE index=%d base=%s source=%s",
            #runtime.poseCandidates, pointerText(base), source
        ))
    end
    for index, delta in ipairs(CONFIG.CANDIDATE_RENDER_RELATIVE_DELTAS) do
        addCandidate(
            runtime.soraRender + delta,
            string.format("render_relative delta=%d candidate=%d", delta, index)
        )
    end
    for index, offset in ipairs(CONFIG.CANDIDATE_BANK_RELATIVE_OFFSETS) do
        addCandidate(
            bank.base + offset,
            string.format("bank_relative bank=%d offset=0x%X candidate=%d",
                bank.index, offset, index)
        )
    end
    emit(string.format(
        "TARGET CANDIDATE VALIDATION READY: exactly %d bounded addresses; one pose read per frame.",
        #runtime.poseCandidates
    ), 1)
    return #runtime.poseCandidates > 0
end

local function acceptTargetPose(pose, source)
    runtime.targetPoseBase = pose.base
    runtime.targetPoseSlots = pose.slots
    runtime.targetRouteReady = true
    runtime.targetRouteFailed = false
    if not setExpectedTarget(runtime.target) then return end
    emit(string.format(
        "TARGET POSE PASS source=%s pose_base=%s slots=%d valid=%d near_actor=%d max_run=%d nearest_actor=%.3f",
        tostring(source), pointerText(pose.base), pose.slots,
        pose.validCount, pose.nearCount, pose.maximumRun, pose.nearest
    ), 1)
    emit(string.format(
        "%s: class=%s joints=%d target published. Ground and action-2 air basic combos may create one qualified selector-4 event per native primary builder transaction; fresh observed offhand contact at radius %.3f is required on every sample;independent offhand-only collision is not installed.",
        runtime.targetRequiresProbation
            and "AUTO-VALIDATED ENEMY PROBATION + OFFHAND READY"
            or "SUPPORTED ENEMY + OFFHAND READY",
        tostring(runtime.targetClass), runtime.targetJointCount,
        CONFIG.CONTACT_RADIUS
    ), 1)
end

local function testNextPoseCandidate()
    local entry = runtime.poseCandidates[runtime.poseCandidateIndex]
    if entry == nil then return end
    runtime.poseCandidateIndex = runtime.poseCandidateIndex + 1
    local position = actorPosition(runtime.target)
    if position == nil then return end
    local pose = probePoseBase(entry.base, position, runtime.targetJointCount)
    if pose == nil then
        emit(string.format(
            "TARGET POSE CANDIDATE PROFILE base=%s source=%s result=unreadable",
            pointerText(entry.base), entry.source
        ), 2)
        return
    end
    emit(string.format(
        "TARGET POSE CANDIDATE PROFILE base=%s source=%s nearest_actor=%.3f valid=%d near_actor=%d max_run=%d",
        pointerText(entry.base), entry.source, pose.nearest,
        pose.validCount, pose.nearCount, pose.maximumRun
    ))
    if pose.nearest > CONFIG.POSE_ACCEPT_NEAREST_DISTANCE
        or pose.validCount < CONFIG.POSE_ACCEPT_MIN_VALID
        or pose.maximumRun < CONFIG.POSE_ACCEPT_MIN_RUN then
        return
    end
    emit(string.format(
        "TARGET POSE CANDIDATE PASS base=%s source=%s nearest_actor=%.3f valid=%d near_actor=%d max_run=%d",
        pointerText(entry.base), entry.source, pose.nearest,
        pose.validCount, pose.nearCount, pose.maximumRun
    ), 1)
    if runtime.bestPoseCandidate == nil
        or pose.nearest < runtime.bestPoseCandidate.pose.nearest then
        runtime.bestPoseCandidate = {
            pose = pose,
            source = entry.source,
        }
    end
end

local function finishPoseRouteIfReady()
    if runtime.poseCandidateIndex <= #runtime.poseCandidates then return end
    if runtime.bestPoseCandidate ~= nil then
        if runtime.targetRequiresProbation then
            if runtime.probationPose == nil then
                runtime.probationPose = runtime.bestPoseCandidate.pose
                runtime.probationPoseSource = runtime.bestPoseCandidate.source
                runtime.probationPoseFrames = 0
                runtime.probationPoseSignatureA =
                    runtime.bestPoseCandidate.pose.signatureA
                runtime.probationPoseSignatureB =
                    runtime.bestPoseCandidate.pose.signatureB
                runtime.probationPoseChanged = false
                emit(string.format(
                    "UNKNOWN MODEL READ-ONLY HOLD START: model_key=%s pose_base=%s required_frames=%d. Target remains unpublished and gate remains zero.",
                    tostring(runtime.targetModelKey),
                    pointerText(runtime.probationPose.base),
                    CONFIG.UNKNOWN_POSE_HOLD_FRAMES
                ), 1)
            end
            return
        end
        acceptTargetPose(
            runtime.bestPoseCandidate.pose,
            runtime.bestPoseCandidate.source
        )
        return
    end
    runtime.targetRouteFailed = true
    local unknownFailed = runtime.targetRequiresProbation
    if unknownFailed and runtime.targetModelKey ~= nil then
        local state = runtime.modelValidation[runtime.targetModelKey]
        if state ~= nil then state.status = "blocked" end
        runtime.targetRequiresProbation = false
    end
    emit(string.format(
        "TARGET POSE NOT FOUND: all %d bounded candidates failed. Gate remains zero; %s",
        #runtime.poseCandidates,
        unknownFailed
            and "an unknown model is quarantined for this Lua session; send this report."
            or "send this report."
    ), 3)
end

local function failUnknownPoseHold(reason)
    local state = runtime.targetModelKey ~= nil
        and runtime.modelValidation[runtime.targetModelKey] or nil
    if state ~= nil then state.status = "blocked" end
    runtime.targetRouteReady = false
    runtime.targetRouteFailed = true
    runtime.targetRequiresProbation = false
    runtime.probationPose = nil
    runtime.probationPoseSource = nil
    runtime.probationPoseFrames = 0
    runtime.probationPoseSignatureA = nil
    runtime.probationPoseSignatureB = nil
    runtime.probationPoseChanged = false
    setExpectedTarget(0)
    emit(string.format(
        "UNKNOWN MODEL READ-ONLY HOLD FAILED / QUARANTINED: model_key=%s reason=%s. Gate remains zero until a full Lua/game restart.",
        tostring(runtime.targetModelKey), tostring(reason)
    ), 3)
end

local function validateUnknownPoseHold()
    local candidate = runtime.probationPose
    if candidate == nil then return end
    local target = runtime.target
    local position = actorPosition(target)
    local hp = targetHpState(target)
    local mobjReference = safeReadInt(
        target + ACTOR_MOBJ_REFERENCE_OFFSET, true
    ) or 0
    local mobj = resolveCompressedPointer(mobjReference)
    local model, jointCount = targetModelFromMobj(mobj)
    if position == nil or hp == nil or hp.currentHp < 1
        or hp.statPage ~= runtime.targetStatPage
        or mobj ~= runtime.targetMobj
        or model ~= runtime.targetModel
        or jointCount ~= runtime.targetJointCount then
        failUnknownPoseHold("exact actor/stat/MOBJ/model/joint identity changed")
        return
    end
    local pose = probePoseBase(candidate.base, position, jointCount)
    if pose == nil
        or pose.nearest > CONFIG.POSE_ACCEPT_NEAREST_DISTANCE
        or pose.validCount < CONFIG.POSE_ACCEPT_MIN_VALID
        or pose.maximumRun < CONFIG.POSE_ACCEPT_MIN_RUN then
        failUnknownPoseHold("selected pose candidate lost structural validity")
        return
    end
    runtime.probationPoseFrames = runtime.probationPoseFrames + 1
    if runtime.probationPoseSignatureA ~= nil
        and runtime.probationPoseSignatureB ~= nil
        and (math.abs(pose.signatureA - runtime.probationPoseSignatureA)
                >= CONFIG.UNKNOWN_POSE_MIN_SIGNATURE_DELTA
            or math.abs(pose.signatureB - runtime.probationPoseSignatureB)
                >= CONFIG.UNKNOWN_POSE_MIN_SIGNATURE_DELTA) then
        runtime.probationPoseChanged = true
    end
    runtime.targetMaximumHp = hp.maximumHp
    runtime.lastHp = hp.currentHp
    if runtime.probationPoseFrames < CONFIG.UNKNOWN_POSE_HOLD_FRAMES then
        return
    end
    if not runtime.probationPoseChanged then
        failUnknownPoseHold("selected pose candidate showed no translation liveness")
        return
    end
    runtime.probationPose = nil
    local source = string.format(
        "%s + read_only_hold_%d",
        tostring(runtime.probationPoseSource),
        CONFIG.UNKNOWN_POSE_HOLD_FRAMES
    )
    runtime.probationPoseSource = nil
    emit(string.format(
        "UNKNOWN MODEL READ-ONLY HOLD PASS: model_key=%s frames=%d liveness_change=true valid=%d max_run=%d nearest_actor=%.3f. Beginning %d-submission native probation.",
        tostring(runtime.targetModelKey), runtime.probationPoseFrames,
        pose.validCount, pose.maximumRun, pose.nearest,
        CONFIG.UNKNOWN_REQUIRED_QUALIFIED
    ), 1)
    acceptTargetPose(pose, source)
end

local function resetTargetRoute(target, reason)
    if runtime.formulaOwner ~= nil then
        setHookFlag(0)
        setExpectedTarget(0)
    end
    runtime.target = target or 0
    runtime.targetIdentityReady = false
    runtime.targetRouteReady = false
    runtime.targetRouteFailed = false
    runtime.targetStatPage = 0
    runtime.targetMaximumHp = 0
    runtime.targetMobj = 0
    runtime.targetModel = 0
    runtime.targetJointCount = 0
    runtime.targetClass = nil
    runtime.targetModelKey = nil
    runtime.targetRequiresProbation = false
    runtime.targetPoseBase = 0
    runtime.targetPoseSlots = 0
    runtime.poseCandidates = {}
    runtime.poseCandidateSeen = {}
    runtime.poseCandidateIndex = 1
    runtime.bestPoseCandidate = nil
    runtime.probationPose = nil
    runtime.probationPoseSource = nil
    runtime.probationPoseFrames = 0
    runtime.probationPoseSignatureA = nil
    runtime.probationPoseSignatureB = nil
    runtime.probationPoseChanged = false
    runtime.lastHp = nil
    runtime.poseReadFailures = 0
    if reason ~= nil then emit("TARGET RESET: " .. tostring(reason), 2) end
end

local function prepareTargetIdentity(target)
    local position = actorPosition(target)
    local hp = targetHpState(target)
    if position == nil or hp == nil then return false end
    local mobjReference = safeReadInt(
        target + ACTOR_MOBJ_REFERENCE_OFFSET, true
    ) or 0
    local mobj = resolveCompressedPointer(mobjReference)
    local model, jointCount = targetModelFromMobj(mobj)
    runtime.targetMobj = mobj
    runtime.targetModel = model
    runtime.targetJointCount = jointCount
    runtime.targetStatPage = hp.statPage
    runtime.targetMaximumHp = hp.maximumHp
    runtime.lastHp = hp.currentHp
    emit(string.format(
        "TARGET IDENTITY target=%s position=(%.3f,%.3f,%.3f) stat_page=%s hp=%d/%d mobj_ref=0x%08X mobj=%s model=%s joints=%d",
        pointerText(target), position.x, position.y, position.z,
        pointerText(hp.statPage), hp.currentHp, hp.maximumHp,
        mobjReference, pointerText(mobj), pointerText(model), jointCount
    ))
    if mobj == 0 or model == 0 then
        runtime.targetRouteFailed = true
        emit(string.format(
            "TARGET FINGERPRINT MISMATCH: readable MOBJ/model required; actual max_hp=%d joints=%d mobj=%s model=%s. Gate remains zero.",
            hp.maximumHp, jointCount, pointerText(mobj), pointerText(model)
        ), 3)
        return true
    end
    runtime.targetModelKey = validationKey(model, jointCount)
    local targetClass = CONFIG.ACCEPTED_TARGET_CLASSES[jointCount]
    if targetClass == nil then
        local exclusion = CONFIG.EXCLUDED_UNKNOWN_JOINT_COUNTS[jointCount]
        if exclusion ~= nil or jointCount < CONFIG.UNKNOWN_MIN_JOINT_COUNT
            or jointCount > CONFIG.UNKNOWN_MAX_JOINT_COUNT then
            runtime.targetRouteFailed = true
            emit(string.format(
                "UNKNOWN TARGET REFUSED: model_key=%s max_hp=%d joints=%d reason=%s. Gate remains zero.",
                runtime.targetModelKey, hp.maximumHp, jointCount,
                tostring(exclusion or "joint-count outside bounded 16..352 range")
            ), 3)
            return true
        end
        local state = runtime.modelValidation[runtime.targetModelKey]
        if state ~= nil and state.status == "blocked" then
            runtime.targetRouteFailed = true
            emit(string.format(
                "UNKNOWN TARGET REFUSED: model_key=%s was quarantined earlier in this Lua session. Gate remains zero.",
                runtime.targetModelKey
            ), 3)
            return true
        end
        if state ~= nil and state.status == "trusted" then
            targetClass = string.format("session-trusted-%d", jointCount)
            runtime.targetRequiresProbation = false
        else
            if state == nil then
                state = {
                    status = "probation",
                    submissions = 0,
                    qualified = 0,
                    duplicateSkips = 0,
                    nativeRefusals = 0,
                }
                runtime.modelValidation[runtime.targetModelKey] = state
            end
            targetClass = string.format("probation-%d", jointCount)
            runtime.targetRequiresProbation = true
        end
    end
    runtime.targetClass = targetClass
    runtime.targetIdentityReady = true
    if runtime.targetRequiresProbation then
        local state = runtime.modelValidation[runtime.targetModelKey]
        emit(string.format(
            "UNKNOWN TARGET CANDIDATE: model_key=%s class=%s joints=%d maximum_hp=%d prior_qualified=%d/%d. Starting bounded read-only validation; target is not published yet.",
            runtime.targetModelKey, targetClass, jointCount, hp.maximumHp,
            state.qualified, CONFIG.UNKNOWN_REQUIRED_QUALIFIED
        ), 1)
    else
        emit(string.format(
            "TARGET FINGERPRINT PASS: class=%s joints=%d maximum_hp=%d state=%s; the guarded Sora chain may now be read.",
            targetClass, jointCount, hp.maximumHp,
            CONFIG.NATIVE_TARGET_MAXIMUM_HP[jointCount] ~= nil
                and hp.maximumHp == CONFIG.NATIVE_TARGET_MAXIMUM_HP[jointCount]
                and "native" or "configured/session-validated"
        ), 1)
    end
    if runtime.soraJoint205 ~= 0 then
        prepareRecordedPoseCandidates()
    end
    return true
end

local function tryCachedSoraPose(model, render)
    if runtime.cachedSoraModel == 0
        or runtime.cachedSoraRender == 0
        or runtime.cachedSoraJointOffset == 0
        or runtime.cachedSoraModel ~= model
        or runtime.cachedSoraRender ~= render then
        return false
    end
    local offset = runtime.cachedSoraJointOffset
    local first = CONFIG.SORA_CHAIN_RUN_FROM_RENDER
    local last = first + CONFIG.SORA_CHAIN_RUN_COUNT * CONFIG.MATRIX_STRIDE
    if offset < first or offset >= last
        or offset % CONFIG.MATRIX_STRIDE ~= 0 then
        emit("SORA OFFHAND POSE CACHE REJECTED: cached offset is outside the exact aligned render run; performing a fresh bounded scan.", 3)
        runtime.cachedSoraModel = 0
        runtime.cachedSoraRender = 0
        runtime.cachedSoraJointOffset = 0
        runtime.cachedSoraPoseStartSlot = -1
        return false
    end
    local candidate = render + offset
    local point = matrixTranslation(candidate)
    local soraPosition = actorPosition(runtime.sora)
    local matrix = readJointMatrix(candidate)
    local anchorDistance = point ~= nil and soraPosition ~= nil
        and distance(point, soraPosition) or math.huge
    if matrix == nil or point == nil
        or anchorDistance > CONFIG.MAX_SORA_ANCHOR_DISTANCE then
        emit(string.format(
            "SORA OFFHAND POSE CACHE REJECTED: exact same-render candidate became unreadable or left the %.1f-unit Sora bound (distance=%.3f); performing a fresh bounded scan.",
            CONFIG.MAX_SORA_ANCHOR_DISTANCE, anchorDistance
        ), 3)
        runtime.cachedSoraModel = 0
        runtime.cachedSoraRender = 0
        runtime.cachedSoraJointOffset = 0
        runtime.cachedSoraPoseStartSlot = -1
        return false
    end
    runtime.soraJoint205 = candidate
    runtime.soraPoseStartSlot = runtime.cachedSoraPoseStartSlot
    emit(string.format(
        "SORA OFFHAND POSE CACHE PASS model=%s render=%s joint205=%s offset=0x%X start_slot=%d sora_distance=%.3f; fresh animation-dependent signature scan skipped.",
        pointerText(model), pointerText(render), pointerText(candidate), offset,
        runtime.cachedSoraPoseStartSlot, anchorDistance
    ), 1)
    if runtime.targetIdentityReady then
        prepareRecordedPoseCandidates()
    end
    return true
end

local function beginSoraPoseRead()
    local pose=Shared.getPose(runtime.sora)
    -- Idle initialization is allowed through the prepared exact pose identity.
    local identity=pose and pose.identity or Shared.trail and Shared.trail.P.ready and Shared.trail.P.identity
    if not identity or identity.route.sora~=runtime.sora then return false end
    local mobj=resolveCompressedPointer(safeReadInt(runtime.sora+ACTOR_MOBJ_REFERENCE_OFFSET,true)or 0)
    local model=mobj~=0 and resolveCompressedPointer(safeReadInt(mobj+0x20,true)or 0)or 0
    local render=resolveCompressedPointer(safeReadInt(runtime.sora+ACTOR_RENDER_REFERENCE_OFFSET,true)or 0)
    if model==0 or render==0 or safeReadInt(model,true)~=CONFIG.EXPECTED_SORA_JOINT_COUNT then return false end
    if runtime.packet==0 and not locateCvbl(model)then
        if not runtime.missingVisualReported then
            emit("VISUAL ASSET REQUIRED: loaded Sora CVBL has no exact joint205 Kingdom Key duplicate packet. Install the included OpenKH model assets;contact damage stays closed.",2)
            runtime.missingVisualReported=true
        end
        return false
    end
    runtime.missingVisualReported=false
    runtime.soraModel=model;runtime.soraRender=render;runtime.soraJoint205=identity.matrixAddress
    runtime.soraPoseReading=false;runtime.soraPoseStartSlot=205
    if runtime.targetIdentityReady then prepareRecordedPoseCandidates()end
    emit("DAMAGE POSE READY: shared direct205 world matrix;legacy chain scan disabled.",false)
    return true
end

local function processSoraPoseRead()
    local last = math.min(
        runtime.soraPoseReadIndex + CONFIG.SORA_CHAIN_MATRICES_PER_FRAME,
        CONFIG.SORA_CHAIN_RUN_COUNT
    )
    for slot = runtime.soraPoseReadIndex, last - 1 do
        runtime.soraPoseTranslations[slot + 1] = matrixTranslation(
            runtime.soraPoseBase + slot * CONFIG.MATRIX_STRIDE
        ) or false
    end
    runtime.soraPoseReadIndex = last
    if runtime.soraPoseReadIndex >= CONFIG.SORA_CHAIN_RUN_COUNT then
        finishSoraPoseRead()
    elseif runtime.soraPoseReadIndex % 64 == 0 then
        emit(string.format(
            "SORA CHAIN READING progress=%d/%d",
            runtime.soraPoseReadIndex, CONFIG.SORA_CHAIN_RUN_COUNT
        ))
    end
end

local function offhandSegment()
    local p=Shared.getPose(runtime.sora);if not p then return nil,nil end
    local a,b=p.geometry.a,p.geometry.b
    return {x=a[1],y=a[2],z=a[3]},{x=b[1],y=b[2],z=b[3]}
end

local function targetPoseContact(first, second, targetPosition)
    if runtime.targetPoseBase == 0 or runtime.targetPoseSlots < 1 then
        return nil
    end
    local bytes = safeReadArray(
        runtime.targetPoseBase,
        runtime.targetPoseSlots * CONFIG.MATRIX_STRIDE,
        true
    )
    if bytes == nil then return nil end
    local valid = 0
    local nearest = math.huge
    local nearestSlot = -1
    for slot = 0, runtime.targetPoseSlots - 1 do
        local position = slot * CONFIG.MATRIX_STRIDE + 1
        local point = affineTranslationFromBytes(bytes, position)
        if point ~= nil
            and distance(point, targetPosition)
                <= CONFIG.MAX_TARGET_MATRIX_DISTANCE then
            valid = valid + 1
            local current = pointSegmentDistance(point, first, second)
            if current < nearest then
                nearest = current
                nearestSlot = slot
            end
        end
    end
    if valid < CONFIG.POSE_ACCEPT_MIN_VALID then return nil end
    return {
        valid = valid,
        nearest = nearest,
        nearestSlot = nearestSlot,
    }
end

local function collisionWindow(sora, slot)
    local pointerArrayReference = safeReadInt(
        sora + ACTIVE_POINTER_ARRAY_OFFSET, true
    ) or 0
    local pointerArray = resolveCompressedPointer(pointerArrayReference)
    if pointerArray == 0 then return nil end
    local motionReference = safeReadInt(pointerArray + slot * 4, true) or 0
    local motion = resolveCompressedPointer(motionReference)
    if motion == 0
        or safeReadInt(motion + 0x00, true) ~= 0
        or safeReadInt(motion + 0x08, true) ~= EXPECTED_FPS_BITS
        or safeReadInt(motion + 0x10, true) ~= CONFIG.EXPECTED_SORA_JOINT_COUNT then
        return nil
    end
    local triggerReference = safeReadInt(motion + 0x3C, true) or 0
    local trigger = resolveCompressedPointer(triggerReference)
    if trigger == 0 then return nil end
    for groupIndex = 0, 15 do
        local row = trigger + groupIndex * 12
        local groupType = safeReadInt(row + 0x00, true) or 0
        if groupType == 0xFFFFFFFF then break end
        local count = safeReadInt(row + 0x04, true) or 0
        local dataReference = safeReadInt(row + 0x08, true) or 0
        if groupType == 0x00010000 and count >= 2 then
            local data = resolveCompressedPointer(dataReference)
            if data == 0 then return nil end
            local startFrame = safeReadFloat(data + 0x00, true)
            local startState = safeReadInt(data + 0x04, true)
            local endFrame = safeReadFloat(data + 0x10, true)
            local endState = safeReadInt(data + 0x14, true)
            if startFrame ~= nil and endFrame ~= nil
                and startState == 1 and endState == 0
                and endFrame >= startFrame then
                return {
                    startFrame = startFrame,
                    endFrame = endFrame,
                    motion = motion,
                }
            end
            return nil
        end
    end
    return nil
end

local function attackKind(action, animation)
    if animation >= 0xC8 and animation <= 0xCB then return "ground" end
    if action == CONFIG.AIR_ACTION
        and animation >= CONFIG.AIR_ANIMATION_MIN
        and animation <= CONFIG.AIR_ANIMATION_MAX
        and runtime.airValidationStatus ~= "blocked" then
        return "air"
    end
    return nil
end

local function startMotion(action, animation, slot, frame)
    local kind = attackKind(action, animation)
    if kind == nil then return end
    local window = collisionWindow(runtime.sora, slot)
    runtime.motionSerial = runtime.motionSerial + 1
    runtime.motion = {
        serial = runtime.motionSerial,
        kind = kind,
        action = action,
        animation = animation,
        slot = slot,
        startFrame = window ~= nil and window.startFrame or math.huge,
        endFrame = window ~= nil and window.endFrame or -math.huge,
        nativeMotion = window ~= nil and window.motion or 0,
        lastFrame = frame,
        activeSamples = 0,
        minimumDistance = math.huge,
        minimumFrame = -1.0,
        minimumTargetSlot = -1,
        contactArmed = false,
        contactConfirmed = false,
        armMode = nil,
        armFrame = nil,
        armDistance = nil,
        predictedForFrame = nil,
        contactFrame = nil,
        contactDistance = nil,
        contactTargetSlot = nil,
        leadSamples = 0,
        predictedMinimumDistance = math.huge,
        predictedMinimumFrame = -1.0,
        previousFirst = nil,
        previousSecond = nil,
        previousFrame = nil,
        contextCaptured = false,
        captureFrame = nil,
        nativeDamage = nil,
        secondarySubmitted = false,
        secondaryQualified = false,
        secondaryRecord = 0,
        secondaryDamage = 0,
        primarySequence = 0,
        primarySelector = 0,
        secondarySequence = 0,
        secondarySelector = 0,
    }
    emit(string.format(
        "MOTION START serial=%d kind=%s action=0x%X animation=0x%02X slot=0x%04X collision=[%.3f,%.3f] native_motion=%s",
        runtime.motion.serial, kind, action, animation, slot,
        runtime.motion.startFrame, runtime.motion.endFrame,
        pointerText(runtime.motion.nativeMotion)
    ))
    -- The request remains closed until fresh observed offhand contact.
    setHookFlag(0)
end

local function finishMotion(reason)
    local motion = runtime.motion
    if motion == nil then return end
    setHookFlag(0)
    if motion.activeSamples > 0 then
        runtime.completedBasicMotions = runtime.completedBasicMotions + 1
        emit(string.format(
            "MOTION RESULT serial=%d animation=0x%02X lead_samples=%d active_samples=%d min_pose_joint_distance=%.3f frame=%.3f target_pose_slot=%d request_armed=%s arm_mode=%s arm_frame=%.3f arm_distance=%.3f predicted_min_distance=%.3f predicted_min_frame=%.3f contact_confirmed=%s contact_frame=%.3f attempted=%s submitted=%s reason=%s",
            motion.serial, motion.animation, motion.leadSamples,
            motion.activeSamples,
            motion.minimumDistance, motion.minimumFrame,
            motion.minimumTargetSlot, tostring(motion.contactArmed),
            tostring(motion.armMode or "none"),
            motion.armFrame or -1.0, motion.armDistance or -1.0,
            motion.predictedMinimumDistance,
            motion.predictedMinimumFrame,
            tostring(motion.contactConfirmed),
            motion.contactFrame or -1.0,
            tostring(motion.contextCaptured),
            tostring(motion.secondarySubmitted), tostring(reason)
        ))
    else
        emit(string.format(
            "MOTION RESULT serial=%d animation=0x%02X active_samples=0 no_valid_collision_pose_sample reason=%s",
            motion.serial, motion.animation, tostring(reason)
        ), 2)
    end
    if motion.armMode == "predicted" and not motion.contactConfirmed then
        runtime.predictiveMisses = runtime.predictiveMisses + 1
        emit(string.format(
            "PREDICTION MISS serial=%d animation=0x%02X predicted_for_frame=%.3f predicted_distance=%.3f submitted=%s",
            motion.serial, motion.animation,
            motion.predictedForFrame or -1.0,
            motion.armDistance or -1.0,
            tostring(motion.secondarySubmitted)
        ), 3)
    end
    if motion.contactArmed and not motion.contextCaptured then
        if runtime.hookFlag == 2 then
            emit(string.format(
                "COMPLETED REQUEST PENDING POLL serial=%d kind=%s animation=0x%02X: motion ended after the machine builder completed; preserved metadata will qualify the result next frame.",
                motion.serial, motion.kind, motion.animation
            ), 1)
        else
            emit(string.format(
                "ARMED REQUEST WITHOUT NATIVE ATTEMPT serial=%d animation=0x%02X arm_mode=%s contact_confirmed=%s: no later native wrapper-to-builder call matched the exact target before this motion ended.",
                motion.serial, motion.animation,
                tostring(motion.armMode or "none"),
                tostring(motion.contactConfirmed)
            ), 2)
        end
    elseif motion.contextCaptured then
        emit(string.format(
            "EQUIPMENT-INTEGRATED OFFHAND RESULT serial=%d animation=0x%02X arm_mode=%s arm_frame=%.3f contact_confirmed=%s contact_frame=%.3f builder_frame=%.3f contact_distance=%.3f primary_damage=%d primary_sequence=%d primary_selector=%d secondary_damage=%d secondary_sequence=%d secondary_selector=%d target_mask_before=0x%08X target_mask_after=0x%08X context_restored=%s submitted=%s qualified=%s",
            motion.serial, motion.animation,
            tostring(motion.armMode or "none"), motion.armFrame or -1.0,
            tostring(motion.contactConfirmed), motion.contactFrame or -1.0,
            motion.captureFrame or -1.0,
            motion.contactDistance or -1.0, motion.nativeDamage or 0,
            motion.primarySequence or 0, motion.primarySelector or 0,
            motion.secondaryDamage or 0, motion.secondarySequence or 0,
            motion.secondarySelector or 0,
            motion.targetMaskBefore or 0, motion.targetMaskAfter or 0,
            tostring(motion.contextRestored),
            tostring(motion.secondarySubmitted),
            tostring(motion.secondaryQualified)
        ), motion.secondaryQualified and 1 or 3)
    end
    runtime.motion = nil
    if runtime.completedBasicMotions - runtime.lastSummaryMotion
        >= CONFIG.SUMMARY_INTERVAL_MOTIONS then
        runtime.lastSummaryMotion = runtime.completedBasicMotions
        emit(string.format(
            "EQUIPMENT-INTEGRATED OFFHAND SUMMARY: motions=%d native_attempts=%d submitted_offhand_events=%d qualified_offhand_events=%d submitted_unqualified=%d predictive_arms=%d predictive_misses=%d. Integration remains active.",
            runtime.completedBasicMotions, runtime.totalAttempts,
            runtime.submittedOffhandEvents,
            runtime.successfulOffhandEvents,
            runtime.rejectedOffhandEvents, runtime.predictiveArms,
            runtime.predictiveMisses
        ), runtime.rejectedOffhandEvents == 0
            and runtime.predictiveMisses == 0 and 1 or 3)
    end
end
local function sampleMotion(frame)
    local motion=runtime.motion
    if motion==nil then return end
    -- Every request needs this frame's observed offhand contact. A prior
    -- contact, an unreadable pose or a later main-hand hit must not keep it open.
    if not setHookFlag(0)then return end
