    if targetPosition==nil or first==nil or second==nil then return end
    local pose=targetPoseContact(first,second,targetPosition)
    if pose==nil then
        runtime.poseReadFailures=runtime.poseReadFailures+1
        if runtime.poseReadFailures<=3 or runtime.poseReadFailures%30==0 then
            emit("TARGET POSE SNAPSHOT WAIT: current offhand contact unverified;request gate closed.",2)
        end
        return
    end
    runtime.poseReadFailures=0;motion.activeSamples=motion.activeSamples+1
    if pose.nearest<motion.minimumDistance then
        motion.minimumDistance=pose.nearest;motion.minimumFrame=frame;motion.minimumTargetSlot=pose.nearestSlot
    end
    local touching=pose.nearest<=CONFIG.CONTACT_RADIUS
    if touching then
        if not motion.contactConfirmed then
            motion.contactConfirmed=true;motion.contactFrame=frame
            motion.contactDistance=pose.nearest;motion.contactTargetSlot=pose.nearestSlot
        end
        if not motion.contactArmed then
            motion.contactArmed=true;motion.armMode="observed";motion.armFrame=frame;motion.armDistance=pose.nearest
            emit(string.format("OFFHAND CONTACT OBSERVED / REQUEST ARMED serial=%d kind=%s animation=0x%02X frame=%.3f nearest_pose_joint_distance=%.3f target_pose_slot=%d valid_pose_points=%d target=%s current_contact_required=true",
