end

local function resetForSora(sora)
    runtime.sora = sora or 0
    runtime.settle = 0
    runtime.soraModel = 0
    runtime.soraRender = 0
    runtime.soraPoseBase = 0
    runtime.soraJoint205 = 0
    runtime.soraPoseReading = false
    runtime.soraPoseReadIndex = 0
