end

function _OnFrame()
    if not runtime.enabled or runtime.stopped then return end
    runtime.tick = runtime.tick + 1
    local lease = privateThemeLeaseState()
    if lease == nil then
        runtime.stopped = true
        runtime.enabled = false
        emit("STOPPED: shared cave is neither the exact OIC1 offhand owner nor the paired PTL1/V82 private-theme lease; no further writes.", 3)
        return
    end
    if lease then
        if not runtime.caveLeaseActive then
            runtime.caveLeaseActive = true
            runtime.caveLeaseCount = runtime.caveLeaseCount + 1
            runtime.hookFlag = 0
            runtime.motion = nil
            runtime.pendingRequestKind = nil
            runtime.pendingRequestAnimation = 0
            runtime.pendingRequestSerial = 0
            runtime.target = 0
            runtime.targetIdentityReady = false
            runtime.targetRouteReady = false
            emit(string.format(
                "PRIVATE-THEME LEASE SUSPEND: native builder CALL verified; offhand sampling paused lease_count=%u.",
                runtime.caveLeaseCount
            ), 1)
        end
        return
    end
    if runtime.caveLeaseActive then
        runtime.caveLeaseActive = false
        resetForSora(0)
        emit("PRIVATE-THEME LEASE RESUME: exact OIC1 cave and builder CALL restored; offhand sampling restarted from a clean route.", 1)
    end
    if not pollHookResult() then return end
    if not monitorFormulaOwner() then return end
    local sora = safeReadLong(SORA_POINTER_RVA, false) or 0
    if sora == 0 then
        if runtime.motion ~= nil then finishMotion("Sora unloaded") end
        setHookFlag(0)
        if runtime.sora ~= 0 then
            emit("ROUTE RESET: Sora unloaded; no stale address will be read.", 2)
            resetForSora(0)
        elseif runtime.tick % 300 == 0 then
            emit("WAIT: Sora field actor is not loaded.")
        end
        return
    end
    if runtime.sora == 0 or runtime.sora ~= sora then
        if runtime.motion ~= nil then finishMotion("Sora actor changed") end
        setHookFlag(0)
        if runtime.sora ~= 0 then
            emit("ROUTE RESET: Sora actor changed; restarting safely.", 2)
        end
        resetForSora(sora)
        emit("SORA DETECTED: " .. pointerText(sora)
            .. "; waiting for a trusted or safely auto-validatable enemy target.")
        return
    end

    if safeReadByte(EQUIPPED_WEAPON_RVA, false)
        ~= CONFIG.KINGDOM_KEY_ITEM_ID then
        if runtime.motion ~= nil then finishMotion("Kingdom Key unequipped") end
        setHookFlag(0)
        if runtime.target ~= 0 then
            resetTargetRoute(0, "Kingdom Key unequipped")
        end
        if runtime.tick % 300 == 0 then
            emit("WAIT: equip Kingdom Key (item 0x51).")
        end
        return
    end

    local target = currentTarget()
    if target == 0 then
        if runtime.motion ~= nil then finishMotion("lock-on target cleared") end
        setHookFlag(0)
        if runtime.target ~= 0 then
            resetTargetRoute(0, "lock-on target cleared")
        elseif runtime.tick % 300 == 0 then
            emit("WAIT: lock a trusted or safely auto-validatable enemy.")
        end
        return
    end
    if runtime.target == 0 or runtime.target ~= target then
        if runtime.motion ~= nil then finishMotion("lock-on target changed") end
        setHookFlag(0)
        resetTargetRoute(target,
            runtime.target ~= 0 and "lock-on target changed" or nil)
        if not prepareTargetIdentity(target) then
            emit("TARGET WAIT: identity route is not readable yet.", 2)
        end
        return
    end
    if not runtime.targetIdentityReady then
        setHookFlag(0)
        if runtime.targetRouteFailed then return end
        prepareTargetIdentity(target)
        return
    end

    -- Unlike V56, the dynamic Sora chain starts only after the exact target
    -- fingerprint has passed. This removes all pre-transition retry reads.
    if runtime.soraJoint205 == 0 then
        setHookFlag(0)
        if runtime.soraPoseReading then
            processSoraPoseRead()
            return
        end
        runtime.settle = runtime.settle + 1
        if runtime.settle < CONFIG.SETTLE_FRAMES then return end
        if not beginSoraPoseRead() then
            runtime.settle = CONFIG.SETTLE_FRAMES - 15
            if runtime.tick % 60 == 0 then
                emit("WAIT: guarded Sora chain or offhand packet is not readable yet.", 2)
            end
        end
        return
    end

    if not runtime.targetRouteReady then
        setHookFlag(0)
        if runtime.targetRouteFailed then return end
        if runtime.probationPose ~= nil then
            validateUnknownPoseHold()
            return
        end
        if #runtime.poseCandidates == 0 then
            prepareRecordedPoseCandidates()
            return
        end
        testNextPoseCandidate()
        finishPoseRouteIfReady()
        return
    end

    local hp = targetHpState(target)
    local mobjReference = safeReadInt(
        target + ACTOR_MOBJ_REFERENCE_OFFSET, true
    ) or 0
    local currentMobj = resolveCompressedPointer(mobjReference)
    local currentModel, currentJointCount = targetModelFromMobj(currentMobj)
    if hp == nil or hp.statPage ~= runtime.targetStatPage
        or currentMobj ~= runtime.targetMobj
        or currentModel ~= runtime.targetModel
        or currentJointCount ~= runtime.targetJointCount
        or validationKey(currentModel, currentJointCount)
            ~= runtime.targetModelKey then
        if runtime.motion ~= nil then finishMotion("target stat route changed") end
        setHookFlag(0)
        resetTargetRoute(target, "target actor/stat/MOBJ/model identity changed or became unreadable")
        prepareTargetIdentity(target)
        return
    end
    if hp.maximumHp ~= runtime.targetMaximumHp then
        emit(string.format(
            "ENEMYCONFIG MAXIMUM-HP UPDATE ACCEPTED: %d->%d; exact actor/stat/MOBJ/model/%d-joint identity is unchanged.",
            runtime.targetMaximumHp, hp.maximumHp, runtime.targetJointCount
        ), 1)
        runtime.targetMaximumHp = hp.maximumHp
        runtime.lastHp = hp.currentHp
    elseif runtime.lastHp ~= nil and hp.currentHp < runtime.lastHp then
        emit(string.format(
            "TARGET HP LOSS hp=%d->%d amount=%d motion_serial=%d context_captured=%s",
            runtime.lastHp, hp.currentHp, runtime.lastHp - hp.currentHp,
            runtime.motion ~= nil and runtime.motion.serial or -1,
            tostring(runtime.motion ~= nil and runtime.motion.contextCaptured)
        ))
    elseif runtime.lastHp ~= nil and hp.currentHp > runtime.lastHp then
        emit(string.format(
            "TARGET HP INCREASE hp=%d->%d",
            runtime.lastHp, hp.currentHp
        ), 2)
    end
    runtime.lastHp = hp.currentHp

    if runtime.packet == 0
        or safeReadInt(runtime.packet + 0x00, true)
            ~= OFFHAND_VISIBLE_MARKER then
        if runtime.motion ~= nil then finishMotion("offhand packet not visible") end
        setHookFlag(0)
        if runtime.tick % 300 == 0 then
            emit("WAIT: validated offhand packet is not visible.", 2)
        end
        return
    end

    local action = safeReadInt(sora + CURRENT_ACTION_OFFSET, true) or 0
    local animation = safeReadByte(sora + CURRENT_ANIMATION_OFFSET, true) or 0
    local slotValue = safeReadInt(sora + RESOLVED_SLOT_OFFSET, true) or 0
    local slot = slotValue % 0x10000
    local frame = safeReadFloat(sora + ANIMATION_FRAME_OFFSET, true) or 0.0
    local kind = attackKind(action, animation)
    if kind == nil then
        if runtime.motion ~= nil then finishMotion("left basic-combo animation") end
        setHookFlag(0)
        return
    end
    local transition = runtime.motion == nil
        or runtime.motion.animation ~= animation
        or runtime.motion.slot ~= slot
        or frame + 0.5 < runtime.motion.lastFrame
    if transition then
        if runtime.motion ~= nil then finishMotion("motion transition/frame reset") end
        startMotion(action, animation, slot, frame)
    end
    if runtime.motion ~= nil then
        runtime.motion.lastFrame = frame
    end
    sampleMotion(frame)
end

