local function unsigned32(value)
    if value == nil then return 0 end
    if value < 0 then return value + 4294967296 end
    return value
end

local function signed32(value)
    local normalized = unsigned32(value)
    if normalized >= 2147483648 then return normalized - 4294967296 end
    return normalized
end

local function safeReadByte(address, absolute)
    local ok, value = pcall(ReadByte, address, absolute == true)
    if not ok or value == nil then return nil end
    return value
end

local function safeReadInt(address, absolute)
    local ok, value = pcall(ReadInt, address, absolute == true)
    if not ok or value == nil then return nil end
    return unsigned32(value)
end

local function safeReadLong(address, absolute)
    local ok, value = pcall(ReadLong, address, absolute == true)
    if not ok or value == nil then return nil end
    return value
end

local function safeReadArray(address, length, absolute)
    local ok, value = pcall(ReadArray, address, length, absolute == true)
    if not ok or value == nil or #value ~= length then return nil end
    return value
end

local function safeWriteInt(address, value, absolute)
    local ok = pcall(WriteInt, address, signed32(value), absolute == true)
    if not ok then return false end
    return safeReadInt(address, absolute) == unsigned32(value)
end

local function pointerText(value)
    if value == nil or value == 0 then return "0x0" end
    local ok, result = pcall(string.format, "0x%X", math.floor(value))
    return ok and result or tostring(value)
end

local function scriptDirectory()
    if type(SCRIPT_PATH) == "string" and #SCRIPT_PATH > 0 then return SCRIPT_PATH end
    if debug == nil or debug.getinfo == nil then return nil end
    local ok, info = pcall(debug.getinfo, 1, "S")
    if not ok or info == nil or info.source == nil then return nil end
    local source = info.source
    if string.sub(source, 1, 1) == "@" then source = string.sub(source, 2) end
    return string.match(source, "^(.*)[\\/]")
end

local function console(message)
    local line = "[KingdomKeyOffhandMarkerGateV1] " .. tostring(message)
    if ConsolePrint ~= nil then pcall(ConsolePrint, line) else pcall(print, line) end
