local function emit(message)Shared.log("MARKER "..tostring(message),false)end

local function readable(address, length)
    return type(address) == "number"
        and address >= 0x10000
        and address <= 0x00007FFFFFFFFFFF
        and safeReadArray(address, length or 0x10, true) ~= nil
