local function validateCvbl(address)
    if address == 0 or not readable(address, 0x10) then return false, "CVBL header unreadable" end
    if safeReadInt(address + 0x00, true) ~= CVBL_MAGIC_OR_VERSION
        or safeReadInt(address + 0x04, true) ~= CVBL_DESCRIPTOR_COUNT
        or safeReadInt(address + 0x08, true) ~= CVBL_FLAGS then
        return false, "CVBL header changed"
    end

    local packet = address + OFFHAND_PACKET_OFFSET
    if not readable(packet, 0x20) then return false, "offhand packet unreadable" end
    local marker = safeReadInt(packet + 0x00, true)
    if not validMarker(marker) then return false, "offhand marker is not a permitted state" end
    if safeReadInt(packet + 0x04, true) ~= OFFHAND_PACKET_SIZE
        or safeReadInt(packet + 0x08, true) ~= OFFHAND_VERTEX_COUNT
        or safeReadInt(packet + 0x0C, true) ~= 0
        or safeReadInt(packet + 0x10, true) ~= OFFHAND_VERTEX_STRIDE
        or safeReadInt(packet + 0x14, true) ~= OFFHAND_VERTEX_COUNT
        or safeReadInt(packet + 0x1C, true) ~= 0 then
        return false, "offhand packet fields changed"
    end
