local function inspectRegistry(registry)
    local seen = {}
    for offset = 0, REGISTRY_POINTER_WINDOW - 8, 8 do
        local candidate = safeReadLong(registry + offset, true) or 0
        if candidate ~= 0 and not seen[candidate] then
            seen[candidate] = true
            local valid, marker = validateCvbl(candidate)
            if valid then return candidate, marker, offset end
        end
